(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-moe-alltoall-ep"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-1\">一 · 一个把 TPOT 拖垮的跨域 All-to-All 事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-2\">二 · 它解决的具体问题：稀疏搬运而非全量激活</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-3\">三 · 它不解决的问题：正交项与边界外的负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-4\">四 · 失败模式的三种形态与判别信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-5\">五 · 与朴素实现的分界：流水而非串行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-6\">六 · 适用边界的工程化表达</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-7\">七 · 边界：它救的是域内解码，救不了跨域木桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-8\">八 · 从 router 输出到发送缓冲：元数据的形状决定后续一切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-9\">九 · All-to-All dispatch：把 $S\\cdot k\\cdot d$ 个元素搬到专家所在 rank</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-10\">十 · 接收端分组与 tcgen05 分组 GEMM：把散乱 token 变成规整 tile</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-11\">十一 · All-to-All combine：木桶效应发生在这一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-12\">十二 · 五步串起来的流水视角与放置约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-13\">十三 · 每一步的代价归因与观测点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-14\">十四 · 失效边界：什么时候重叠失效、木桶出现、跨域吞掉收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-15\">十五 · 流水线断点：combine 的木桶效应与跨域回落的判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-16\">十六 · 层时延公式的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-17\">十七 · 加权求和公式与跨 rank 的搬运项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-18\">十八 · 分桶与发送缓冲的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-19\">十九 · 重叠编排：把 dispatch 藏进 GEMM 的影子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-20\">二十 · 元数据与门控权重的搬运账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-21\">二十一 · 从公式到容量与放置的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-22\">二十二 · 重叠收益的边界：何时这套调度会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-23\">二十三 · 请求形态与长度分布：什么负载喂得饱 All-to-All</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-24\">二十四 · 并发与批大小：重叠窗口的宽度由谁决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-25\">二十五 · 负载配方：拓扑、专家放置与批参数的联合选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-26\">二十六 · 负载不对时会发生什么：三类失效与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-27\">二十七 · 配方与量化、KV 压缩的正交叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-28\">二十八 · 配方的工程判据：从指标到参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-29\">二十九 · 负载配方：小 batch 解码是主粮，长序列与大并发是毒药</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-30\">三十 · 硬件档位：先定 NVLink 域，再谈节点数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-31\">三十一 · 并行拓扑：EP 度、专家放置与 TP 的配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-32\">三十二 · 量化方案：与调度正交，但要匹配分组 GEMM 的粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-33\">三十三 · KV 策略与显存预算：把专家权重和分页 KV 放进同一本账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-34\">三十四 · 调度参数：容量因子、重叠窗口与超时</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-35\">三十五 · 可复现的配置思路：从校准到压测的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-36\">三十六 · 配方落地时的失效边界：从拓扑约束到慢 rank 木桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-37\">三十七 · 层时延的加性分解：谁在关键路径上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-38\">三十八 · 显存的三份账：激活、发送缓冲、专家权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-39\">三十九 · 带宽的两个域：NVLink 域内与跨节点 IB</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-40\">四十 · 通信与计算的流水：重叠窗口有多宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-41\">四十一 · 尾延迟与功耗：木桶效应与固定开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-42\">四十二 · 规模扩张的崩点排序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-43\">四十三 · 规模放大后先崩的三条线：跨域流量、combine 木桶与功耗墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-44\">四十四 · 精度漂移：从 dispatch 元数据到 combine 加权</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-45\">四十五 · OOM：分页 KV 与专家权重的地址空间争抢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-46\">四十六 · 批抖动与路由不均：容量因子之外的真实分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-47\">四十七 · 尾延迟尖刺：木桶效应与最慢 rank</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-48\">四十八 · 监控面与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-49\">四十九 · 工程判断：把失败模式变成准入条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-50\">五十 · 失效边界：从木桶效应到跨域回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-51\">五十一 · 选型的第一性问题：把&quot;搬运谁&quot;钉死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-52\">五十二 · 决策表：五个维度的交叉判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-53\">五十三 · 与容量因子路由、专家选择路由的接口关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-54\">五十四 · 与分离式部署、投机解码的组合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-55\">五十五 · 否决条件与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-moe-alltoall-ep-sec-56\">五十六 · 同族对照：何时该用 All-to-All 重叠，何时该退回别的形态</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:486px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 486.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"404.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">router 产出 token→专家映射，按目标 rank 聚合为发送缓冲</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"404.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">All-to-All dispatch 将 token 及其元数据发往专家…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"404.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接收端按本地专家分组，tcgen05 分组 GEMM 计算</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"404.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">All-to-All combine 将专家输出送回原 token 所在 …</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"404.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按原 token 位置加权求和，写回 KV/激活缓冲</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-moe-alltoall-ep-sec-1\">一 · 一个把 TPOT 拖垮的跨域 All-to-All 事故</h3>\n<p>某在线推理集群在 NVLink 域内做专家并行时，解码 TPOT 稳定在可接受区间。一次扩容把专家数翻倍，专家放置脚本按 rank 编号顺序平铺，结果一部分热门专家被排到了第二个节点。流量结构随即改变：原本只在 NVSwitch 内搬运的 token，开始大量落到跨节点 IB 路径上。事故的表现不是吞吐下降，而是 TPOT 的尾部急剧拉长——平均时延看起来还行，但 P99 越过 SLO 红线，前端触发限流，有效吞吐反而掉下来。根因不是 GEMM 变慢，也不是量化精度问题，而是 MoE 层的时间被 dispatch 与 combine 两段通信主导。</p>\n<p>把这一层的时延写成可诊断的形式：</p>\n<div class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</div>\n<p>其中 $S$ 为 batch 内 token 数，$k$ 为每 token 激活的专家数（TopK），$d$ 为单 token 激活维度字节数，分母是实际可用的互联带宽。这个式子的关键在于 max：dispatch 与分组 GEMM 若能重叠，通信就被藏在计算后面；一旦重叠失效，两项相加，事故里正是这种情形。而 combine 前面没有 max，它必须等所有专家 rank 完成，最慢的那个 rank 决定整层时延——木桶效应直接写进了公式结构里。事故中的跨域 rank 就是那只最短的木板。</p>\n<p>从系统代价看，这条路径同时吃三样东西：带宽（跨域 IB 的有效带宽远低于 NVLink，$T_{\\text{dispatch}}$ 被放大）、显存（发送/接收缓冲按目标 rank 分桶驻留，域越大缓冲越多）、以及流水线占用（combine 的等待让 SM 在分组 GEMM 结束后空转）。功耗层面则表现为计算单元已 idle 而互联仍在满负荷搬运，能效比恶化。这就是为什么这个算法值得单独成篇：它要解决的不是“MoE 能不能算”，而是“token 能不能以可预测的代价到达专家”。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-2\">二 · 它解决的具体问题：稀疏搬运而非全量激活</h3>\n<p>问题的精确表述是：专家分散在多卡或多节点之后，每个 token 只被路由到 TopK 个专家，这 TopK 个专家所在的 GPU 未必是 token 当前所在的 GPU，因此 $x_t$ 必须先搬到专家所在设备才能参与 $\\mathrm{GEMM}_e$。整层的数学形式是</p>\n<div class=\"formula\">$$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$$</div>\n<p>$g_{t,e}$ 是 router 门控权重，求和跨的是被选中的少数专家。注意这个求和里每一项都在不同 rank 上算出来，所以 combine 阶段要把各专家的部分和送回 token 原属 rank 再按 $g_{t,e}$ 加权。算法真正解决的问题，是把“按 token 的目标专家做稀疏搬运”这件事做成一条可重叠的流水，而不是先全量 dispatch 再串行 GEMM。</p>\n<p>与纯张量并行的对比能说明边界：张量并行每个 rank 都要处理全量激活的分片，通信量随隐藏维度线性增长且与路由无关；All-to-All 调度只搬被路由到的 token，搬运量与 $S\\cdot k$ 成正比，与专家总数无关。代价是搬运的目的地不规则，需要按目标 rank 分桶、附带元数据（原 token 位置、门控权重），接收端还要按本地专家重新分组。这套元数据开销在小 batch 解码时占比很高，正是低延迟模式要压掉的部分。</p>\n<p>一个具体例子：解码 batch 内只有数十个 token，每 token TopK=8，专家分布在 NVLink 域内的多个 rank 上。此时分组 GEMM 的绝对时间很短，dispatch 的固定开销（建桶、元数据打包、同步）反而成了主项。若这些 rank 全在 NVSwitch 域内，走纯 NVLink 路径可以把固定开销压到与 GEMM 同量级，max 才有意义；一旦有 token 跨域，IB 的往返延迟直接把 $T_{\\text{dispatch}}$ 顶到 GEMM 之上，重叠设计失效。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-3\">三 · 它不解决的问题：正交项与边界外的负载</h3>\n<p>必须明确划出不适用的范围，否则工程上容易把 SLO 问题错记到这个算法头上。第一，它不解决量化精度与显存压缩：NVFP4/FP8 的微缩放、分页 KV 与专家权重共存，都是与调度正交的独立层，可以叠加但不由此算法承担。第二，它不解决路由质量：容量因子与令牌丢弃、专家选择路由属于 router 侧策略，调度只忠实执行 router 给出的映射；映射本身倾斜，再好的 All-to-All 也只是把倾斜搬运得更快。第三，它不解决预填阶段的大吞吐问题——分块预填与解码 piggyback、预填解码分离部署是另一条路径，本算法的收益集中在解码小 batch 的低延迟区间。</p>\n<p>第四，它不适用于专家完全本地化的部署：若每个 rank 上的 token 恰好只路由到本 rank 的专家，All-to-All 退化为空操作，此时瓶颈在分组 GEMM 本身。第五，它不解决单卡放不下专家时的容量问题——那是显存与专家放置的联合约束，调度只能在给定放置下优化流量。第六，它不替代集合通信库的可靠性机制；NCCL/NIXL 层的超时与重传是另一层，调度假设通信原语可用。</p>\n<p>适用边界可以压缩成一句工程判断：规模上限由 NVLink 域大小与 IB 带宽共同决定。域内 rank 越多，稀疏搬运相对全量激活的优势越明显；跨域比例上升后，All-to-All 延迟会吞掉重叠收益。材料未给出具体带宽数字，因此容量规划必须以实测的域内/跨域时延比为输入，而不是按 rank 数线性外推。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-4\">四 · 失败模式的三种形态与判别信号</h3>\n<p>第一种是专家放置不当。放置脚本按编号平铺、不看路由分布，热门专家被推到跨域 rank，大量 token 走 IB。判别信号很直接：把 dispatch 时延按源-目的 rank 对拆开，若跨域对的时延贡献超过域内对一个数量级，且与 GEMM 时间不再满足 max 关系，就是放置问题而非计算问题。修复手段是把专家放置约束在 NVLink 域内，让域内走纯 NVLink All-to-All，跨节点才回落 IB。</p>\n<p>第二种是 combine 的木桶效应。combine 必须等所有专家 rank 完成，任一慢 rank 拖住整层。判别信号是层时延的方差：若 $T_{\\text{combine}}$ 的分布长尾明显而 $T_{\\text{GEMM}}$ 稳定，说明等待发生在汇合点。工程上可做的是让 dispatch 与分组 GEMM 重叠以隐藏前半段通信，但对 combine 只能靠负载均衡与放置优化缩短最慢 rank，无法用重叠消除——这是公式结构决定的，不是实现缺陷。</p>\n<p>第三种是小 batch 误走 IB。解码 batch 小、每 token 仅激活 TopK 个专家时，通信固定开销占比高；若低延迟模式没有生效、请求被路由到 IB 路径，重叠设计直接失效。判别信号是 batch 大小与 TPOT 的关系曲线出现反常：小 batch 时延不降反升，说明固定开销没有被 NVLink 域内路径吸收。稳定性技巧因此收敛为两条：dispatch 与分组 GEMM 重叠隐藏通信；专家放置约束在 NVLink 域内减少跨域流量。</p>\n<p>把三种形态放一起看，它们共享同一个结构：算法的收益来自 max 把通信藏进计算，而任何让 $T_{\\text{dispatch}}$ 或 $T_{\\text{combine}}$ 脱离这个结构的事件都会把收益清零。事故复盘的价值不在于记住某次扩容，而在于把“跨域比例”和“最慢 rank”做成上线前的两个必查指标。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-5\">五 · 与朴素实现的分界：流水而非串行</h3>\n<p>与逐专家独立 launch 的朴素实现相比，本算法的差别不在数学，而在时间结构。朴素实现先全量 dispatch，再对每个本地专家串行 launch GEMM，最后 combine；三段严格串行，$T_{\\text{layer}}=T_{\\text{dispatch}}+T_{\\text{GEMM}}+T_{\\text{combine}}$，通信完全暴露。本算法把 dispatch 与分组 GEMM 做成可重叠的流水，用 max 取代加号，这是唯一但决定性的改动。代价是接收端必须在数据到达的同时按本地专家分组，分桶与 GEMM 的启动顺序被打乱，实现复杂度上升。</p>\n<p>一个具体机制例子：router 产出 token 到专家的映射后，按目标 rank 聚合为发送缓冲；All-to-All dispatch 把 token 及其元数据发往专家所在 rank；接收端按本地专家分组，用 tcgen05 分组 GEMM 计算；combine 把专家输出送回原 token 所在 rank；最后按原 token 位置加权求和，写回 KV/激活缓冲。整条链上，只有 dispatch 段能与 GEMM 重叠，combine 段是硬同步点。因此调度的优化重心应放在“让 dispatch 尽早开始、让每个 rank 的本地专家尽快凑齐可算的分组”，而不是平均地优化三段。</p>\n<p>系统代价上，重叠不是免费的：发送缓冲与接收缓冲要同时驻留，显存占用随域内 rank 数增长；重叠要求 SM 在通信进行时仍有可执行的 GEMM 分组，小 batch 下分组太碎会导致 GEMM 启动开销吃掉重叠收益。这就是为什么低延迟模式在 NVLink 域内避免走 IB 对小 batch 解码收益显著——它压的是固定开销，而固定开销正是小 batch 下 max 失效的主因。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-6\">六 · 适用边界的工程化表达</h3>\n<p>把边界写成可执行的判据：给定一次部署，先测域内 All-to-All 的时延与跨域时延之比，再测解码 batch 下 $T_{\\text{GEMM}}$ 的量级。若跨域时延已超过 $T_{\\text{GEMM}}$，则重叠设计对该部署无效，应优先改专家放置而不是调调度参数；若域内时延与 $T_{\\text{GEMM}}$ 同量级，则 max 成立，收益随域内 rank 数增加而增加。这两个测量不需要精确的带宽数字，只需要相对关系，因此可以在材料未给出具体带宽的情况下仍做出工程判断。</p>\n<p>另一个判据是 batch 规模：解码阶段 token 数少、每 token 仅激活 TopK 个专家，SLO 以 TPOT 为主，此时调度收益最大；当 batch 增大到分组 GEMM 成为主项，All-to-All 的相对权重下降，优化重心应转向分组 GEMM 的核效率与量化融合。这说明本算法不是全局最优解，而是特定负载区间的最优解——它的适用边界由“通信是否仍是主项”划定，而不是由模型规模划定。</p>\n<p>最后落在机制上：这套调度的本质是把 MoE 层的临界路径从“通信加计算”改写为“通信与计算取大再加汇合”，而汇合点的木桶效应无法被重叠消除。因此任何部署决策都应围绕两个杠杆展开——把专家放置约束在 NVLink 域内以压低 $T_{\\text{dispatch}}$ 的跨域分量，以及通过负载均衡缩短最慢 rank 以压低 $T_{\\text{combine}}$。当这两个杠杆都用尽而 TPOT 仍不达标时，问题已经越出本算法的边界，应转向分离式专家并行或预填解码分离的部署形态。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-7\">七 · 边界：它救的是域内解码，救不了跨域木桶</h3>\n<p>先看一次典型的线上劣化：某 MoE 解码服务在扩容时把专家并行从单节点 8 卡扩到跨两个节点，吞吐指标没掉，但 TPOT 尾延迟突然抬高。原因不在 GEMM——router 映射显示热门专家被放到了远端 rank，大量 token 的 dispatch 落到 IB 上，而 NVLink 域内的 All-to-All 带宽远高于跨节点 IB。此时层时延由 <span class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</span> 中的 $T_{\\text{dispatch}}$ 项主导，重叠设计被通信吞掉：dispatch 不再能被分组 GEMM 掩盖，combine 又必须等所有专家 rank 完成，最慢的那个跨域 rank 决定整层。这个案例划出了本方案的适用边界——它解决的是“token 必须搬到专家所在 GPU”这一稀疏搬运问题，并且只在 NVLink/NVSwitch 域内能把搬运藏进计算；它不解决专家放置本身的不均衡，也不解决跨域带宽不足。</p>\n<p>失效条件可以归成三类，工程上要能提前识别。<table class=\"mini\"><thead><tr><th>条件</th><th>表现</th><th>系统代价落点</th></tr></thead><tbody><tr><td>专家放置跨 NVLink 域</td><td>dispatch 回落 IB，跨域 token 比例上升</td><td>TPOT 抬升，重叠收益被吞</td></tr><tr><td>combine 木桶</td><td>任一慢 rank 拖住整层</td><td>整层时延取最慢 rank，非均值</td></tr><tr><td>小 batch 误走 IB 路径</td><td>固定开销占比过高</td><td>通信延迟主导，流水空转</td></tr></tbody></table>注意第三类最隐蔽：解码 batch 内 token 少、每 token 只激活 TopK 个专家，DeepEP 低延迟模式的价值恰恰在于 NVLink 域内绕开 IB；一旦拓扑配置让它走了 IB，重叠机制在数学上仍然成立，实际却退化成“先全量 dispatch 再串行 GEMM”的朴素实现。</p>\n<p>它明确不解决的问题也要说清：不替代张量并行做全量激活切分（本方案只搬被路由到的 token，属稀疏搬运）；不与量化、KV 压缩冲突也不解决它们——NVFP4 权重与分层 KV 可正交叠加，但不会让跨域 All-to-All 变快；不解决容量规划与批调度层面的 SLO 违约，只把 MoE 层的通信-计算流水做紧。规模上限由 NVLink 域大小与 IB 带宽共同约束：域内 rank 越多收益越明显，跨域比例一旦上升，$T_{\\text{dispatch}}$ 与 $T_{\\text{combine}}$ 的固定开销就会吃掉重叠红利。判断是否该上这套调度，先量一件事——被路由 token 中跨 NVLink 域的比例，而不是先看 GPU 数量。</p>\n<h3 id=\"alg-moe-alltoall-ep-sec-8\">八 · 从 router 输出到发送缓冲：元数据的形状决定后续一切</h3>\n<p>按数据流拆解，第一步不是通信而是“编址”。router 对每个 token 产出 TopK 个（专家，门控权重）对，这一步的输出不是张量而是索引结构：对 batch 内 $S$ 个 token，得到形状为 $S\\times k$ 的专家 ID 矩阵与同形状的权重矩阵。调度器要做的第一件事是把这两个矩阵按目标 rank 做一次转置式重排——不是按 token 顺序，而是按“目的地”顺序。具体做法是：先对专家 ID 做一次 rank 映射（专家到 rank 的放置表），再对 $S\\cdot k$ 个（token, 专家）对做稳定排序或计数排序，得到每个目标 rank 的发送偏移与长度，写入发送缓冲的头部元数据区。</p>\n<p>这一步的输入是 router 的索引输出与专家放置表，输出是每个 rank 的发送段描述符（偏移、token 数、每个 token 的原始位置与门控权重）。代价上，它是纯片上操作，不占 NVLink 带宽，但占 SM 周期与寄存器：$S\\cdot k$ 个元素的排序在解码小 batch 下可忽略，在分块预填的大 $S$ 下会成为可见的固定开销，因此工程上通常把它与上一层 combine 的尾部重叠，或用一个轻量 kernel 与 KV 写回并行发射。关键判断是：元数据必须与 token 激活一起走，否则接收端无法把结果送回原位——这条约束贯穿后面四步。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-9\">九 · All-to-All dispatch：把 $S\\cdot k\\cdot d$ 个元素搬到专家所在 rank</h3>\n<p>dispatch 的输入是打包好的发送缓冲：每个目标 rank 一段连续的 token 激活（维度 $d$）加上对应的元数据（原 token 位置、门控权重、目标本地专家 ID）。输出是接收端每个 rank 上的“待计算 token 池”。搬运量按公式估算：</p>\n<div class=\"formula\">$$T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</div>\n<p>系数 2 来自“发出去再收回来”的对称性口径，单看 dispatch 只算单向；$S$ 是 batch 内 token 数，$k$ 是 TopK，$d$ 是隐藏维。这条公式给出的直接工程结论是：解码阶段 $S$ 很小，$T_{\\text{dispatch}}$ 的绝对值不大，但固定启动开销占比高；预填阶段 $S$ 大，搬运量线性上升，带宽成为硬约束。</p>\n<p>机制上，NVLink 域内用 NVSwitch 的全互联做 rank 间点对点写，DeepEP 低延迟模式在这一层绕开 IB  verbs 的队列对建立与内存注册开销，直接走 NVLink 路径，使小 batch 解码的固定开销降到可与 kernel launch 相比的量级。跨节点才回落 IB，此时带宽远低于 NVLink，同样的 $S\\cdot k\\cdot d$ 搬运量会把 $T_{\\text{dispatch}}$ 推高一个量级。一个具体例子：8 卡 NVLink 域内做 EP=8，全部专家落在域内，dispatch 全程不出节点；一旦 EP 扩到 16 跨两节点，一半的（token, 专家）对要走 IB，即使计算没变，层时延也被 dispatch 主导。代价指标应盯住“跨域流量占比”而非总流量——前者决定 $B$ 取 NVLink 还是 IB。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-10\">十 · 接收端分组与 tcgen05 分组 GEMM：把散乱 token 变成规整 tile</h3>\n<p>接收端的输入是来自多个源 rank 的 token 池，每个 token 携带目标本地专家 ID。输出是各专家的输出激活。中间有一道不可省略的重排：按本地专家 ID 把 token 分组，使同一专家的 token 在缓冲中连续，才能喂给分组 GEMM。这一步的代价是显存侧的散射写——token 从接收缓冲搬到按专家分组的计算缓冲，搬运量等于接收量，但因为是片上/近端显存内的重排，带宽压力落在 SMEM/L2 而非 NVLink。</p>\n<p>计算侧用 tcgen05 的分组 GEMM：多个专家的矩阵乘在一次 MMA 发射中按组切换权重指针与 token 段，避免逐专家独立 launch 带来的发射开销与尾效应。数学上这一层就是</p>\n<div class=\"formula\">$$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$$</div>\n<p>其中 $x_t$ 已经在 dispatch 阶段被搬到 $e$ 所在设备，$g_{t,e}$ 随 token 一起到达。工程上要盯的是分组 GEMM 的 tile 利用率：解码小 batch 下每个专家收到的 token 数很少，若某专家只收到个位数 token，其 GEMM 的有效 $M$ 维极低，算力利用率被拉垮。这正是分组 GEMM 与 dispatch 重叠的动机——把通信时间塞进这段低利用率区间，而不是让两者串行叠加。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-11\">十一 · All-to-All combine：木桶效应发生在这一步</h3>\n<p>combine 的输入是各本地专家的输出激活及其元数据（原 token 位置、门控权重），输出是回到原 token 所在 rank 的专家输出。搬运量与 dispatch 对称，但代价结构不同：dispatch 可以按目的地分批流水，combine 却必须先等本地所有专家的 GEMM 全部完成才能打包发回——因为一个 token 的多个专家结果可能分散在多个 rank，接收端要凑齐 TopK 份才能加权求和。</p>\n<p>这带来两个具体代价。其一是同步点：combine 的发射时刻由最慢的专家 rank 决定，任一 rank 因负载偏斜或显存抖动晚完成，整层就被拖住，形成木桶效应式的流水线停顿。其二是接收端的归约：原 rank 收到 $k$ 份来自不同 rank 的输出后，要按原 token 位置做散射累加，写回 KV/激活缓冲；这一步的显存写带宽与 dispatch 的读带宽同量级，但因为是累加而非覆盖，需要读-改-写，实际占用更高。层时延因此写成</p>\n<div class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}}$$</div>\n<p>公式里 combine 不在 max 之内，这是结构性的：dispatch 能与 GEMM 重叠，combine 不能，因为它依赖 GEMM 的完整输出。所以优化重心应放在压缩 $T_{\\text{combine}}$ 本身——用更短的跨域路径、把专家放置约束在 NVLink 域内使 combine 也走 NVLink，以及让负载在 rank 间尽量均衡以缩小最慢 rank 与平均值的差距。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-12\">十二 · 五步串起来的流水视角与放置约束</h3>\n<p>把五步按时间轴排开：编址（片上）→ dispatch（NVLink/IB）→ 分组重排（显存）→ 分组 GEMM（tcgen05）→ combine（NVLink/IB）→ 加权写回（显存）。可重叠的窗口只有 dispatch 与 GEMM 之间，做法是把 dispatch 按目标 rank 切成若干块，第一块到达即启动对应专家的 GEMM，后续块陆续到达陆续追加，形成通信-计算流水；这与“先全量 dispatch 再串行 GEMM”的朴素实现相比，把两段串行时间压成一段 max 时间。</p>\n<p>放置约束是这套流水能否成立的前提。专家放置表决定每个（token, 专家）对走 NVLink 还是 IB；把高流量专家对约束在 NVLink 域内，等于把 $B$ 锁在高带宽档。反过来，若专家按参数均衡而非流量均衡放置，热门专家被放到远端节点，跨域比例上升，dispatch 与 combine 同时被 IB 带宽拖慢，重叠收益被吞掉。可用事实给出的边界是：域内 rank 越多收益越明显，跨域比例上升后 All-to-All 延迟会吞掉重叠收益；材料未给出具体带宽数字，因此容量规划时应以“跨域流量占比”作为一阶指标，而非以总 token 数估算。</p>\n<p>小 batch 解码还有一个易踩的坑：若调度路径误判拓扑、把本可走 NVLink 的流量送进 IB，固定开销（队列建立、注册、轮询）在 $S$ 很小时占比极高，重叠设计直接失效。判断依据不是 batch 大小本身，而是“本次 dispatch 的目的 rank 是否全在 NVLink 域内”。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-13\">十三 · 每一步的代价归因与观测点</h3>\n<p>把代价按步归因，才能定位瓶颈在哪一段。编址步看 SM 周期占比与是否与上一层尾部重叠；dispatch 步看跨域流量占比与 NVLink 有效带宽利用率；分组重排看 L2/SMEM 散射写的冲突率；分组 GEMM 看每专家的有效 $M$ 与 tile 利用率；combine 看最慢 rank 与平均 rank 的时延差（木桶间隙）以及归约写回的读-改-写放大。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th><th>可重叠对象</th></tr></thead><tbody>\n<tr><td>编址</td><td>router 索引、放置表</td><td>按 rank 的发送段描述符</td><td>SM 周期、寄存器</td><td>上一层 combine 尾部</td></tr>\n<tr><td>dispatch</td><td>发送缓冲</td><td>接收端 token 池</td><td>NVLink/IB 带宽、固定启动开销</td><td>分组 GEMM（分块流水）</td></tr>\n<tr><td>分组重排</td><td>token 池、本地专家 ID</td><td>按专家连续的缓冲</td><td>显存散射写、L2 冲突</td><td>与 dispatch 尾块并行</td></tr>\n<tr><td>分组 GEMM</td><td>分组缓冲、专家权重</td><td>专家输出激活</td><td>低 $M$ 下的算力利用率</td><td>后续 dispatch 块</td></tr>\n<tr><td>combine</td><td>专家输出、元数据</td><td>回原 rank 的输出</td><td>最慢 rank 同步、跨域带宽</td><td>不可与 GEMM 重叠</td></tr>\n<tr><td>加权写回</td><td>$k$ 份输出、门控权重</td><td>KV/激活缓冲</td><td>读-改-写显存带宽</td><td>下一层编址</td></tr>\n</tbody></table>\n<p>工程判断落在两处：其一，$T_{\\text{combine}}$ 是公式中唯一不在 max 内的项，压缩它的收益是线性的、无条件的，优先于继续优化 dispatch 与 GEMM 的重叠度；其二，专家放置表的更新应以实测跨域流量占比为反馈信号，而不是按参数均衡一次性定死——解码流量的热点会随请求分布漂移，放置需要跟着漂。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-14\">十四 · 失效边界：什么时候重叠失效、木桶出现、跨域吞掉收益</h3>\n\n<p>这套调度并非在所有规模下都成立。它的收益来自两个前提：dispatch 能与分组 GEMM 真正重叠，且搬运主要发生在 NVLink 域内。一旦任一前提被破坏，公式 $T_{\\text{layer}}=\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})+T_{\\text{combine}}$ 里的 max 就退化为求和——通信不再被隐藏，而是直接加到关键路径上。最直接的触发条件是专家放置跨出 NVLink 域：当大量 token 的目标专家落在别的节点，dispatch 只能回落 IB，而 IB 带宽远低于 NVLink，$T_{\\text{dispatch}}=\\frac{2Skd}{B_{\\text{NVLink}}}$ 中的分母被换成一个更小的量，单层时延立刻由通信主导而非计算主导。此时即使 GEMM 再快，重叠也只是让 GEMM 空等，流水线重新空转。</p>\n\n<p>第二个失效条件是 combine 的木桶效应。combine 必须等所有专家 rank 完成本地分组 GEMM 才能启动，整层时延由最慢 rank 决定。解码阶段每 token 只激活 TopK 个专家，token 在 rank 间的分布天然不均：热门专家所在 rank 的 GEMM 队列更长，冷门 rank 早早算完却只能等待。这种不均衡在小 batch 下被放大——batch 内 token 数少，统计平滑不起作用，单 rank 的排队延迟直接暴露在 TPOT 上。工程上的判断是：专家放置必须同时约束“域内”和“均衡”两个维度，只满足其一会把收益让给另一个瓶颈。</p>\n\n<p>第三个失效条件是小 batch 误走 IB 路径。DeepEP 低延迟模式的价值恰恰在于 NVLink 域内绕开 IB，把通信固定开销压到可接受范围；若拓扑配置错误或专家放置越界，小 batch 解码会带着 IB 的固定握手与协议开销跑，这部分开销与 token 数几乎无关，占比随 batch 变小而急剧上升，重叠设计彻底失效。下表给出三种边界下的代价归属，便于在部署时定位瓶颈：</p>\n\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>关键路径主导项</th><th>系统代价表现</th></tr></thead><tbody><tr><td>专家全在 NVLink 域内且分布均衡</td><td>$\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})$</td><td>时延接近纯计算，TPOT 稳定</td></tr><tr><td>跨域比例上升</td><td>$T_{\\text{dispatch}}$（IB 带宽受限）</td><td>解码时延被通信主导，吞吐随跨域 token 比例线性恶化</td></tr><tr><td>域内但专家分布倾斜</td><td>$T_{\\text{combine}}$（最慢 rank）</td><td>木桶停顿，整层时延由单 rank 排队决定</td></tr></tbody></table>\n\n<p>把这些边界折进设计，需要在 router 之后加一层放置感知的约束：按目标 rank 聚合发送缓冲时同时统计跨域 token 比例与各 rank 的预计 GEMM 负载，超阈值就触发专家重放置或 token 重路由，而不是让 All-to-All 硬扛。$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$ 中跨 rank 的 $x_t$ 必须先经 dispatch 搬到 $e$ 所在设备，这一步的代价是可预测的——它正比于被路由 token 的字节数而非全量激活，因此容量规划时应以“跨域 token 比例 × 单 token 激活字节”估算 IB 流量，并把它作为专家并行拓扑的硬约束，而非事后调优项。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-15\">十五 · 流水线断点：combine 的木桶效应与跨域回落的判定</h3>\n<p>按数据流拆开看，这条流水线真正脆弱的不是 dispatch，而是 combine。dispatch 阶段每个 rank 只需把自己桶里的 token 发出去，发送量由本 rank 的 router 结果决定，负载相对均匀；combine 阶段则相反，每个 rank 必须收齐所有发往它本地专家的 token 计算结果，再按原 token 位置加权求和写回 KV/激活缓冲。于是整层时延由最慢 rank 决定：<div class=\"formula\">$$T_{\\text{combine}}=\\max_{r}\\left(T_{\\text{GEMM},r}+T_{\\text{send},r}\\right)$$</div>只要某个 rank 因为专家放置不均而多背了热点专家的 token，它的分组 GEMM 就会拖长，其余 rank 全部空转等待。重叠设计在 dispatch 侧隐藏通信，却无法在 combine 侧隐藏这种尾部延迟——这是重叠方案的结构性边界，不是调参能消除的。</p>\n<p>第二个边界是跨域比例。NVLink 域内的 All-to-All 与分组 GEMM 可以做成流水，一旦 token 需要跨节点走 IB，dispatch 的固定开销和带宽落差会直接吞掉重叠收益。可用一个粗略判据：设域内 token 占比为 $\\rho$，跨域流量近似正比于 $(1-\\rho)$，则当跨域传输时间超过分组 GEMM 时间时，<div class=\"formula\">$$\\frac{2(1-\\rho)S k d}{B_{\\text{IB}}}&gt;T_{\\text{GEMM}}\\;\\Rightarrow\\;\\text{重叠失效}$$</div>此时层时延退化为串行的 dispatch + GEMM + combine，与朴素逐专家 launch 的差距迅速收窄。工程判断因此落在专家放置上：把高频共现的专家约束在同一 NVLink 域，使 $\\rho$ 尽量接近 1；域内 rank 越多，收益越明显，但域大小本身受 NVSwitch 拓扑限制。</p>\n<p>第三个失效条件是小 batch 误走 IB。解码阶段每 token 仅激活 TopK 个专家，token 数少意味着单次 All-to-All 的有效载荷很小，通信的固定开销（建链、元数据、同步）占比骤升。DeepEP 低延迟模式的价值正在于此时绕开 IB、走纯 NVLink 路径，把固定开销压到与 payload 同量级；若调度器在 batch 很小时仍按跨节点拓扑分发，重叠设计会因同步等待而空转。代价体现在 TPOT 上：通信主导时，TPOT 不再随计算量下降，而是被一个与 batch 大小弱相关的常数项托底。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>dispatch</td><td>token 激活 + 元数据</td><td>按目标 rank 分桶的发送缓冲</td><td>NVLink/IB 带宽，跨域时陡增</td></tr><tr><td>分组 GEMM</td><td>本地专家桶</td><td>专家输出</td><td>tcgen05 算力，受最热专家约束</td></tr><tr><td>combine</td><td>各 rank 专家输出</td><td>加权求和后的激活</td><td>木桶效应，最慢 rank 决定时延</td></tr></tbody></table>\n<h3 id=\"alg-moe-alltoall-ep-sec-16\">十六 · 层时延公式的逐项拆解</h3>\n<p>把 MoE 层当成一个两段式流水来看，整层时延写成 <span class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}}$$</span> 这个式子的关键不在形式，而在它把 dispatch 与 GEMM 放进同一个 max 里——这意味着二者被设计成并发执行，而不是先全量搬运再串行计算。max 而不是加号，正是重叠设计的数学表达：当 dispatch 时间被 GEMM 完全覆盖时，层时延退化为 <span class=\"formula\">$$T_{\\text{layer}}\\approx T_{\\text{GEMM}}+T_{\\text{combine}}$$</span>，通信在关键路径上被消掉，只剩 combine 这一段的固定开销。反过来，如果 dispatch 远大于 GEMM（跨节点 IB 场景），max 取到 dispatch，重叠收益被通信吞没，整层就变成通信主导。这个式子因此也是判断“该不该做重叠”的判据：只有当 <span class=\"formula\">$$T_{\\text{dispatch}}\\lesssim T_{\\text{GEMM}}$$</span> 时，重叠才有意义；否则优化方向应转向专家放置而非流水编排。</p>\n<p>第二项 <span class=\"formula\">$$T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</span> 里，$S$ 是 batch 内 token 数，$k$ 是每 token 激活的专家数（TopK），$d$ 是单 token 激活向量的字节宽度（含量化后的实际位宽），$B_{\\text{NVLink}}$ 是域内聚合带宽。分子上的 2 来自一次往返：dispatch 把 token 送出去、combine 把结果送回来，两段搬运量对称，所以带宽项按双向计。$S\\cdot k$ 是搬运的“份数”——每个 token 被复制 $k$ 份发往 $k$ 个专家所在 rank，这是 All-to-All 相对张量并行的本质差异：只搬被路由到的副本，而非全量激活。$d$ 这一项直接连到量化决策：NVFP4 权重与激活把 $d$ 压到 FP8 的一半以下，dispatch 时间随之近似线性下降，这也是量化与调度正交、可叠加的原因。</p>\n<p>把这个式子代回解码场景就能看出瓶颈结构。解码阶段 $S$ 很小（连续批处理下每步可能只有个位数到几十个 token），$k$ 通常为 8 量级，$d$ 在 NVFP4 下是几百字节量级，分子很小；此时 $T_{\\text{dispatch}}$ 的绝对值不大，但固定开销（kernel launch、元数据打包、同步）占比陡增，所以小 batch 下走 NVLink 纯域内路径、避免 IB 回落，是让分母 $B_{\\text{NVLink}}$ 保持高位、同时压掉固定开销的关键。工程判断：解码阶段的 All-to-All 优化重点不是“搬得更快”，而是“别让固定开销和跨域跳数把分子分母同时做坏”。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-17\">十七 · 加权求和公式与跨 rank 的搬运项</h3>\n<p>专家计算的语义由 <span class=\"formula\">$$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$$</span> 给出。$g_{t,e}$ 是 router 门控权重，$\\mathrm{GEMM}_e$ 是专家 $e$ 的本地分组矩阵乘，$x_t$ 是 token 激活。这个式子在单卡上是纯粹的加权和；一旦专家分散，$x_t$ 必须先经 All-to-All dispatch 搬到 $e$ 所在设备，公式就要改写为带搬运算子的形式：<span class=\"formula\">$$y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e\\big(\\mathrm{Dispatch}(x_t,\\,r(e))\\big)$$</span>，其中 $r(e)$ 是专家 $e$ 所在 rank。推导的关键一步在这里：求和号内的每一项都依赖不同的 rank，因此 combine 必须等所有 $e$ 的 GEMM 完成才能开始加权——这不是实现细节，而是公式结构决定的串行约束。$g_{t,e}$ 的加权在 combine 端做，意味着 combine 不仅要搬数据，还要带着门控权重一起回传或在原 rank 侧保留权重表；后者更省带宽，代价是原 rank 要维护 token 到权重的映射直到 combine 结束。</p>\n<p>把求和拆成“本地项 + 远端项”能直接看出流量结构：<span class=\"formula\">$$y_t=\\underbrace{\\sum_{e\\in\\mathrm{TopK}(t),\\,r(e)=r(t)} g_{t,e}\\mathrm{GEMM}_e(x_t)}_{\\text{本地，零搬运}}+\\underbrace{\\sum_{e\\in\\mathrm{TopK}(t),\\,r(e)\\neq r(t)} g_{t,e}\\mathrm{GEMM}_e(\\mathrm{Dispatch}(x_t))}_{\\text{远端，走 All-to-All}}$$</span>。第一项不产生任何跨设备流量，第二项的项数就是该 token 的跨 rank 副本数。专家放置优化的目标因此可以量化：最小化所有 token 上第二项的期望项数，等价于让 TopK 命中的专家尽量落在同一 NVLink 域内。当放置不当、第二项占比升高时，$T_{\\text{dispatch}}$ 的分子实际变大（跨域副本要走 IB，等效带宽骤降），max 取到 dispatch，层时延被通信主导——这就是失败模式在公式层面的样子。</p>\n<p>代价侧要盯住 combine 的木桶效应。combine 的时延不是平均值而是最大值：<span class=\"formula\">$$T_{\\text{combine}}=\\max_{r\\in\\mathcal{R}}T_{\\text{combine}}(r)$$</span>，$\\mathcal{R}$ 是参与本层的 rank 集合。任一 rank 的专家 GEMM 慢一拍，整层就被拖住。这与 max 结构叠加后形成两级 max：dispatch 与 GEMM 重叠是一级，combine 等最慢 rank 是二级。工程上因此要把负载均衡（容量因子、token 分布）与专家放置一起看，否则公式再漂亮，最慢 rank 仍是关键路径。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-18\">十八 · 分桶与发送缓冲的伪代码</h3>\n<p>落到可实现，第一步是把 router 输出变成按目标 rank 聚合的发送缓冲。核心是一个计数-前缀和-散射的三段式，避免逐 token 动态扩容：</p>\n<ul>\n<li>遍历本 rank 的 $S$ 个 token，对每个 token 的 TopK 专家查放置表得到目标 rank，累加 <code>count[r]</code>；</li>\n<li>对 <code>count</code> 做前缀和得到每个目标 rank 在发送缓冲中的起始偏移 <code>offset[r]</code>；</li>\n<li>再遍历一次，把 token 激活与元数据（原 token 位置、门控权重索引）散射到 <code>buf[offset[r]++]</code>。</li>\n</ul>\n<p>伪代码思路：<code>for t in tokens: for e in topk(t): r = rank_of(e); idx = offset[r]++; buf[idx] = pack(x[t], t, g[t,e])</code>。这个循环的代价是 $O(S\\cdot k)$ 次访存写，在解码小 batch 下可忽略，但在分块预填的大 batch 下会成为不可忽视的 CPU/GPU 侧开销，所以实现上通常把放置表做成常量内存查表、把 pack 做成向量化写。发送缓冲的大小由 <code>count</code> 的上界决定，需要按容量因子上限预分配，否则动态扩容会引入同步点，破坏与 GEMM 的重叠。</p>\n<p>接收端的对称操作是“按本地专家分组”：All-to-All 收到的 token 是按来源 rank 排列的，必须先按本地专家重排成分组 GEMM 需要的连续段。这一步用同样的计数-前缀和-散射，只是键从“目标 rank”换成“本地专家 id”。分组 GEMM 的输入布局（每个专家的 token 数、起始偏移）由此确定，直接喂给 tcgen05 的分组矩阵乘。代价点在于：重排是一次全量访存搬移，$S\\cdot k\\cdot d$ 字节在接收缓冲与 GEMM 输入之间再走一遍，显存带宽成为这一段的实际瓶颈；把重排与 dispatch 的接收融合（收到即写入目标专家的段）能省掉这一趟，但要求发送端按专家 id 而非 rank 排序，牺牲了发送端的聚合度。这是实现里必须做的取舍。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-19\">十九 · 重叠编排：把 dispatch 藏进 GEMM 的影子</h3>\n<p>重叠不是把两个 kernel 同时 launch 就完事，而是要构造依赖关系让 dispatch 的搬运与上一段 GEMM 的计算在时间上交错。可行的编排是把层切成“专家块”粒度：当第 $j$ 个专家的分组 GEMM 在算时，第 $j+1$ 个专家所需的 token 正在被 dispatch 搬入。伪代码层面表现为双缓冲：<code>recv_buf[0]</code> 供当前 GEMM 读，<code>recv_buf[1]</code> 接收下一批；<code>wait(arrive[1])</code> 与 <code>gemm(recv_buf[0])</code> 之间没有数据依赖，硬件可以把搬运的 DMA 与 tensor core 的算力并行占用。这就是 max 公式在实现上的对应物：只要 <code>T_dispatch(chunk)</code> 不超过 <code>T_GEMM(chunk)</code>，搬运就被完全隐藏。</p>\n<p>代价与边界要算清楚。双缓冲把接收侧显存需求翻倍，$2\\cdot S\\cdot k\\cdot d$ 字节常驻，在 KV cache 与专家权重已经占满显存的情况下，这个增量必须从分页 KV 的预留里抠出来——这也是显存规划要把 All-to-All 缓冲与 KV 池一起算的原因。另一个代价是同步粒度：块切得越细，重叠越充分，但每块的 GEMM 效率越低（tcgen05 的 tile 利用率下降），且同步原语（mbarrier/arrive-wait）的次数线性上升。工程判断是让块大小对齐分组 GEMM 的 tile 形状，而不是一味求细。跨节点场景下，IB 的 dispatch 时延远大于 NVLink，块级重叠也救不回 max 取到 dispatch 的局面，此时应优先收缩 NVLink 域、把跨域副本数压到最低，而不是继续调流水参数。</p>\n<p>一个具体例子：解码步内 $S$ 很小、$k$ 为 8，若专家全部落在同一 NVLink 域，dispatch 走纯 NVLink 路径，$T_{\\text{dispatch}}$ 被 $T_{\\text{GEMM}}$ 覆盖，层时延接近纯计算；一旦有若干 token 的 TopK 命中跨节点专家，这些副本回落 IB，$T_{\\text{dispatch}}$ 抬升到 max 之上，整层时延立刻由通信项主导，重叠设计失效。这说明重叠的收益是有条件的，条件就写在 max 里。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-20\">二十 · 元数据与门控权重的搬运账</h3>\n<p>公式里只写了 $x_t$ 的搬运，实现里还有一笔常被低估的账：元数据。每个副本要带原 token 位置（用于 combine 回填）和门控权重（用于加权求和），这两项每副本各几个字节，乘以 $S\\cdot k$ 后在小 $d$ 的 NVFP4 场景下占比不可忽略。两种设计：其一是元数据随激活一起打包发送，接收端 GEMM 后原样带回，优点是自包含、无额外状态；其二是元数据留在原 rank，只发一个 token id，combine 时按 id 查本地权重表，优点是省带宽，缺点是要维护 id 到位置的映射表并在 combine 时随机查表。推导上的判据是：当 $d$ 被量化压得很小时，元数据的相对开销上升，第二种设计更划算；当 $d$ 较大（FP8/FP16 激活）时，第一种的打包开销可忽略，实现更简单。</p>\n<p>这笔账直接影响 combine 的时延项。combine 要把专家输出送回原 rank 并按 $g_{t,e}$ 加权求和，若权重在本地，combine 端只做“收数据 + 乘权重 + 累加”，访存模式是顺序的；若权重随数据回传，则多一次解包。前者在木桶效应下更稳，因为最慢 rank 的拖累不会被额外的解包放大。代价侧还要注意：combine 的搬运量与 dispatch 对称（公式里的 2 就来自这里），所以 combine 的带宽占用与 dispatch 同级，两者在时间上不重叠（combine 在 GEMM 之后），这意味着 All-to-All 的带宽在层内被占用两段，容量规划要按双向峰值而非单向均值来留余量。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-21\">二十一 · 从公式到容量与放置的工程判断</h3>\n<p>把三个式子联立，可以得到一个用于放置决策的不等式：要让重叠生效，需 <span class=\"formula\">$$\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}\\le T_{\\text{GEMM}}$$</span>，而 $T_{\\text{GEMM}}$ 随本地专家承载的 token 数增长。放置优化的方向因此明确：提高落在同一 NVLink 域内的 TopK 命中比例，既降低有效分子（跨域副本不计入 NVLink 带宽项），又让本地 GEMM 更饱满、抬高分母。反过来，若域内 rank 数增加导致每 rank 分到的专家变少、单专家 GEMM 变小，分母下降，重叠窗口收窄——这就是“域内 rank 越多收益越明显”与“规模上限受 NVLink 域大小约束”两句话在公式上的同一来源，收益与窗口是同一枚硬币的两面。</p>\n<p>容量规划上，All-to-All 缓冲、KV cache、专家权重三者共享显存，双缓冲与元数据表都要计入。带宽侧按双向峰值留余量，因为 dispatch 与 combine 不重叠。时延侧按两级 max 估算：一级是 dispatch 与 GEMM 的 max，二级是 combine 的最慢 rank。任何一级的估算若把平均值当关键路径，容量就会系统性偏乐观。最后落在具体机制上：把专家放置表做成编译期常量、把分桶与重排融合进接收路径、把块大小对齐 tcgen05 tile——这三件事决定了公式里的 max 究竟能不能取到 GEMM，而不是停在纸面上。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-22\">二十二 · 重叠收益的边界：何时这套调度会失效</h3>\n<p>公式 $T_{\\text{layer}}=\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})+T_{\\text{combine}}$ 的成立前提是 dispatch 与 GEMM 真正并行，而 $T_{\\text{dispatch}}=2Skd/B_{\\text{NVLink}}$ 中的 $k$ 是每 token 激活的专家数、$d$ 是单 token 搬运的字节量。关键一步在于：$\\max(\\cdot)$ 只在 $T_{\\text{dispatch}}\\le T_{\\text{GEMM}}$ 时退化为 $T_{\\text{GEMM}}$，一旦跨域比例上升、有效带宽从 $B_{\\text{NVLink}}$ 掉到 $B_{\\text{IB}}$，$T_{\\text{dispatch}}$ 迅速超过分组 GEMM，重叠设计就从“隐藏通信”变成“通信主导”。此时 $T_{\\text{layer}}\\approx T_{\\text{dispatch}}+T_{\\text{combine}}$，解码 TPOT 被 All-to-All 直接钉死，与算力无关。</p>\n<p>第二处失效在 combine：它必须等所有专家 rank 完成，$T_{\\text{combine}}$ 由最慢 rank 决定，而非平均值。专家放置倾斜时，热点 rank 的 GEMM 队列变长，整层时延被木桶效应拖住——即使 dispatch 已被完全隐藏，这一项也无法被重叠吸收。因此调度器应把“每 rank 承载的 token 数方差”作为放置约束，而不是仅按专家数量均分。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>层时延主导项</th><th>系统代价</th></tr></thead><tbody><tr><td>全 NVLink 域、小 batch</td><td>$T_{\\text{GEMM}}$</td><td>通信近零额外开销</td></tr><tr><td>跨节点比例升高</td><td>$T_{\\text{dispatch}}$</td><td>IB 带宽成瓶颈，重叠失效</td></tr><tr><td>专家放置倾斜</td><td>$T_{\\text{combine}}$</td><td>慢 rank 拖停整层流水</td></tr></tbody></table>\n<p>可实现层面，伪代码需显式区分两条路径：若目标 rank 全部落在本 NVLink 域，走 DeepEP 低延迟模式、按 rank 分桶后直接发起域内 All-to-All 并与本地分组 GEMM 的 tcgen05 流水交错；一旦检测到跨域目标，则先按域聚合再回落 IB，并把该层的 $T_{\\text{dispatch}}$ 预估与 $T_{\\text{GEMM}}$ 比较，超过阈值就退化为“先全量 dispatch 再串行 GEMM”的保守路径，避免重叠空转。小 batch 下若误走 IB，固定启动开销占比过高，重叠收益归零——这是最隐蔽的失效条件。</p>\n<h3 id=\"alg-moe-alltoall-ep-sec-23\">二十三 · 请求形态与长度分布：什么负载喂得饱 All-to-All</h3>\n<p>All-to-All 调度不是“任何 MoE 负载都能快”的通用加速器，它对请求形态有明确偏好。机制上，dispatch 阶段搬运的字节量取决于被路由 token 的激活维度与 TopK，而不是 batch 里所有 token 的总量；因此负载是否“喂得饱”，看的是<b>每个 rank 在单次 dispatch 中实际发出的 token 数</b>与<b>这些 token 的目标 rank 分布是否均匀</b>。解码阶段每个请求每步只产生一个 token，若并发请求数少，单 rank 发出的 token 数可能只有个位数，此时 NVLink 的固定启动开销（描述符交换、同步屏障、元数据打包）在总时延中占比极高，重叠设计无从谈起。</p>\n<p>长度分布的影响体现在两个方向。长上下文请求在分块预填阶段会产生成块的 token 洪流，dispatch 的字节量按 <span class=\"formula\">$$T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</span> 随 token 数 $S$ 线性增长，此时通信是带宽受限而非延迟受限，重叠收益明显；而解码阶段每步只有单 token，$S$ 极小，公式退化为固定开销主导。混合负载里若长预填块与短解码步交错，调度器必须决定是否把预填块与解码步拼进同一次 dispatch——拼进去会拉长解码步的等待，拆开则预填块单独走带宽路径。工程判断是：<b>长度分布越接近“预填块大、解码步稳定并发”的双峰形态，All-to-All 越容易做重叠</b>；若负载以大量短请求、低并发为主，通信固定开销会吃掉全部收益。</p>\n<p>代价侧的具体例子：一个 8 卡 NVLink 域内、每卡放 8 个专家的拓扑，若并发解码请求只有 4 个、每 token TopK=8，则单 rank 平均发出的 token 数不足 4 个，dispatch 的元数据与同步开销与有效载荷同量级，TPOT 被通信固定项拉长；反之并发拉到数十请求、每 rank 发出数十 token，dispatch 进入带宽受限区，重叠才有意义。这里不给出具体带宽数字，但判断标准是清晰的：<b>单 rank 有效载荷字节数必须显著大于协议固定开销字节数</b>。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-24\">二十四 · 并发与批大小：重叠窗口的宽度由谁决定</h3>\n<p>重叠的前提是 dispatch 与分组 GEMM 能同时在时间轴上铺开，而铺开需要“下一批 token 已经在路上”。机制上，DeepEP 低延迟模式把 dispatch 做成流水：当前 batch 的 token 发出后，接收端一边收一边按本地专家分组，tcgen05 分组 GEMM 在收到足够 token 后即可启动，而不必等全量 dispatch 完成。这个流水能否填满，取决于<b>批大小是否足以让 GEMM 的持续时间覆盖 dispatch 的持续时间</b>。若 GEMM 太短（小 batch、专家矩阵乘规模小），dispatch 还没走完 GEMM 就结束了，重叠退化为串行；若 GEMM 太长而 dispatch 带宽不足，则 GEMM 等数据，流水线空转。</p>\n<p>把层时延写成 <span class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}}$$</span> 就能看出配方的核心：要让 $\\max$ 取到接近 $T_{\\text{GEMM}}$，必须让 $T_{\\text{dispatch}}$ 不大于 $T_{\\text{GEMM}}$，也就是批大小要大到 dispatch 被完全隐藏。批大小不足时 $\\max$ 由 dispatch 主导，加卡加专家都不解决问题，因为瓶颈在固定开销与跨域带宽。反过来，批大小过大时 $T_{\\text{GEMM}}$ 主导，dispatch 被隐藏，但 combine 阶段仍需等所有专家 rank 完成，最慢 rank 决定整层时延，木桶效应在超大 batch 下更明显——某个 rank 分到的 token 多、GEMM 慢，其余 rank 全部空等。</p>\n<p>具体例子：同一拓扑下，批大小从个位数增到数十 token 时，$T_{\\text{dispatch}}$ 从固定开销主导转为带宽主导并趋于平稳，而 $T_{\\text{GEMM}}$ 随 token 数增长，两者交叉点就是重叠开始生效的批大小门槛。工程上应把连续批处理的调度目标设为“让每 rank 的 token 数落在交叉点右侧”，而不是盲目追求更大 batch——更大 batch 会把 combine 的木桶效应放大。代价是显存：更大 batch 意味着更多在途 token 的激活缓冲与元数据缓冲驻留，分页 KV 与专家权重共存显存的前提下，这部分缓冲会挤压 KV 块的空间。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-25\">二十五 · 负载配方：拓扑、专家放置与批参数的联合选择</h3>\n<p>负载配方不是单一参数，而是“请求形态 × 批大小 × 专家放置 × 互联域”的联合约束。机制上，专家放置决定 token 的目标 rank 分布：若把同一专家的副本或高频共现的专家放在同一 NVLink 域内，dispatch 的跨域比例下降，$T_{\\text{dispatch}}$ 走纯 NVLink 路径；若专家按哈希均匀撒到多节点，高频 token 的目标 rank 分散，跨节点 IB 流量上升，而 IB 带宽远低于 NVLink，$T_{\\text{dispatch}}$ 被放大。配方的一条硬约束是：<b>把专家放置约束在 NVLink 域内，让域内 rank 承担绝大多数 dispatch 流量</b>，跨域只在域容量不足时回落 IB。</p>\n<p>批参数与放置要一起调。若域内 rank 数多、每 rank 专家少，单次 dispatch 的目标 rank 分布更均匀，木桶效应弱，但每个专家的 GEMM 规模变小、$T_{\\text{GEMM}}$ 变短，重叠窗口变窄；若域内 rank 少、每 rank 专家多，GEMM 变长利于隐藏 dispatch，但单 rank 负载集中，combine 的最慢 rank 更突出。配方应在“域内 rank 数”与“每 rank 专家数”之间取平衡，并用连续批处理把解码步的并发维持在交叉点之上。</p>\n<p>具体例子：一个 NVLink 域内 8 rank、每 rank 8 专家的放置，配合数十并发解码请求，dispatch 走纯 NVLink、GEMM 时长足以覆盖 dispatch，层时延接近纯计算时间；若把其中一半专家挪到第二节点，跨域 token 比例上升，IB 路径的 dispatch 时长超过 GEMM，$\\max$ 由通信主导，重叠失效。代价侧：跨域比例每上升一档，dispatch 的有效带宽下降一档，而 combine 的等待时间不变，整层时延的方差也随之变大——这对 SLO 以 TPOT 为主的解码服务是直接的风险。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-26\">二十六 · 负载不对时会发生什么：三类失效与可观测信号</h3>\n<p>第一类失效是<b>小 batch 误走 IB</b>。解码并发低、每 rank token 数少时，若调度器没有识别出“这是小 batch 解码步”，仍按跨域路径走 IB，通信固定开销占比过高，重叠设计完全失效，TPOT 被固定开销拉长。可观测信号是 dispatch 字节量极小但 dispatch 时长不随 batch 缩小而缩短——说明瓶颈在协议开销而非带宽。对策是让低延迟模式在 NVLink 域内短路 IB，并把小 batch 解码步与预填块分离调度。</p>\n<p>第二类失效是<b>专家放置不当放大跨域流量</b>。router 的 token 到专家映射若与专家放置不匹配，大量 token 的目标 rank 落在别的节点，dispatch 带宽被 IB 限制，$T_{\\text{dispatch}}$ 超过 $T_{\\text{GEMM}}$，$\\max$ 由通信主导。可观测信号是跨域 dispatch 字节占比与 dispatch 时长同步上升，而 GEMM 利用率下降。对策是把专家放置与路由分布对齐，必要时做专家复制把热点专家拉到域内。</p>\n<p>第三类失效是<b>combine 的木桶效应</b>。combine 必须等所有专家 rank 完成，任一慢 rank 拖住整层。负载不均时（某 rank 分到远超平均的 token 数），该 rank 的 GEMM 时长决定整层时延，其余 rank 空等。可观测信号是各 rank 的 GEMM 完成时间方差变大，层时延跟随最慢 rank 而非平均 rank。对策是在 dispatch 阶段做负载均衡（按目标 rank 的 token 数做再分配），或把容量因子路由与令牌丢弃作为兜底——但那属于其他条目的主题，此处只指出它是 combine 木桶效应的外部缓解手段。</p>\n<p>三类失效的共同代价是：重叠窗口被压缩甚至消失，层时延从“接近纯计算”退化为“通信主导”，而显存侧的在途缓冲与元数据缓冲仍按原配方驻留，等于用显存换了零收益。工程判断是：<b>负载配方必须先验证单 rank 有效载荷与跨域比例两个指标，再谈批大小与重叠</b>；指标不达标时，加卡只会放大跨域流量与木桶效应，不会缩短 TPOT。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-27\">二十七 · 配方与量化、KV 压缩的正交叠加</h3>\n<p>负载配方与量化、KV 压缩是正交的：NVFP4 权重与激活微缩放量化压缩的是 GEMM 的输入字节与计算吞吐，分层 KV 压缩的是 KV 驻留显存，两者都不改变 dispatch 的 token 数与目标 rank 分布，因此配方可以在量化之上独立调。机制上，量化让 $T_{\\text{GEMM}}$ 变短，这会<b>收窄重叠窗口</b>——原本靠 GEMM 时长隐藏 dispatch 的批大小，在量化后可能不再够用，$\\max$ 重新被 dispatch 主导。这是一个容易被忽略的联动：量化提速后，负载配方必须同步下调批大小门槛或提高并发，否则重叠失效。</p>\n<p>具体例子：同一拓扑下，权重从 FP8 换到 NVFP4 后 GEMM 时长缩短，若批大小不变，$T_{\\text{dispatch}}$ 相对变长，$\\max$ 从 GEMM 主导转为 dispatch 主导，层时延不降反升。对策是把连续批处理的并发目标随量化档位一起上调，让 dispatch 重新被隐藏。代价侧：更高并发意味着更多在途激活缓冲，与分层 KV 的显存预算直接竞争，配方要在“并发够高以隐藏 dispatch”与“显存够放 KV 块”之间取平衡。</p>\n<p>配方与分离式预填/解码部署的联动同样具体：预填节点产生大块 token 洪流，走带宽受限路径；解码节点走低延迟小 batch 路径。两者若共用同一套专家放置，预填的跨域流量会挤占解码的 NVLink 带宽，解码 TPOT 的方差上升。工程判断是：<b>预填与解码的专家放置应分别按各自的流量形态优化，而不是复用一套拓扑</b>；解码侧优先保证域内纯 NVLink，预填侧优先保证跨域带宽的稳定供给。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-28\">二十八 · 配方的工程判据：从指标到参数</h3>\n<p>把配方落到可执行判据，需要三个观测量：单 rank 单次 dispatch 的有效载荷字节数、跨域 dispatch 字节占比、各 rank GEMM 完成时间的方差。第一个指标决定重叠是否可能（有效载荷必须显著大于协议固定开销），第二个决定 $T_{\\text{dispatch}}$ 是否被 IB 放大，第三个决定 combine 的木桶效应是否主导层时延。三者都达标时，批大小可以往交叉点右侧推；任一不达标时，先修放置与路径，再谈批参数。</p>\n<p>机制上，这三个指标对应调度器的三个决策点：是否把小 batch 解码步路由到低延迟模式、是否把专家复制到域内以压低跨域比例、是否在 dispatch 阶段做按目标 rank 的负载再均衡。每个决策点都有明确的代价：低延迟模式限制域内 rank 数，专家复制占用显存与 GEMM 算力，再均衡增加元数据开销。配方就是在这些代价之间取一个让 $\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})$ 接近 $T_{\\text{GEMM}}$、且 combine 方差可控的点。</p>\n<p>最后落在具体机制上：当量化把 $T_{\\text{GEMM}}$ 压短、而跨域比例又因专家放置无法下降时，正确的工程动作不是继续加并发去“喂饱” dispatch，而是先把专家放置收进 NVLink 域、把小 batch 解码步短路到纯 NVLink 路径——因为此时 $\\max$ 的瓶颈在通信路径而非批大小，加并发只会同时放大在途缓冲与 combine 方差。配方的稳定性来自“先修路径、再调批”的顺序，而不是反过来。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-29\">二十九 · 负载配方：小 batch 解码是主粮，长序列与大并发是毒药</h3>\n<p>这套调度方案的设计重心是<strong>解码阶段的小 batch 请求</strong>：batch 内 token 数少、每 token 只激活 TopK 个专家，SLO 由单 token 时延（TPOT）主导。此时 dispatch 的字节量小，DeepEP 低延迟模式能在 NVLink 域内绕开 IB，把通信压进分组 GEMM 的阴影里。但负载一旦偏离这个配方，收益立刻反转。判据可以写成域内流量占比的粗估：设 $S$ 为层内待搬运 token 数、$k$ 为 TopK、$d$ 为隐藏维、$B_{\\text{NVLink}}$ 为域内带宽，则域内 dispatch 时间约 $\\frac{2Skd}{B_{\\text{NVLink}}}$，跨域部分按 IB 带宽折算后叠加。当跨域 token 比例上升，$T_{\\text{dispatch}}$ 迅速越过 $T_{\\text{GEMM}}$，重叠设计失去意义——层时延退化为 $\\max$ 项被通信锁死。</p>\n<p>失效形态有三种，各有明确的系统代价。其一，<strong>专家放置不当</strong>：热门专家集中在少数 rank 上，大量 token 被迫跨节点走 IB，而 IB 带宽远低于 NVLink，解码时延由通信而非计算主导，TPOT 出现长尾。其二，<strong>木桶效应</strong>：combine 必须等所有专家 rank 完成，最慢 rank 决定整层时延；只要一个 rank 上堆了过多专家或负载不均，整条流水线停顿，吞吐随 batch 增大反而恶化。其三，<strong>小 batch 误走 IB</strong>：固定开销占比过高，重叠窗口被吃掉，通信完全暴露。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>匹配度</th><th>主导代价</th></tr></thead><tbody><tr><td>小 batch 解码、短输出</td><td>最佳</td><td>NVLink 域内 dispatch，接近纯计算</td></tr><tr><td>长 prompt 预填、大 batch</td><td>差</td><td>dispatch 字节量放大，跨域 IB 饱和</td></tr><tr><td>专家热度倾斜</td><td>差</td><td>慢 rank 拖住 combine，TPOT 长尾</td></tr></tbody></table>\n<p>工程判断落在两处：把专家放置约束在 NVLink 域内，使跨域比例成为可观测的容量指标而非事后故障；对长序列或大并发请求，宁可退回张量并行或改用分离式预填/解码，让预填走计算密集路径、解码留在低延迟 All-to-All 路径上，而不是让同一套专家并行拓扑硬扛两种形态。</p>\n<h3 id=\"alg-moe-alltoall-ep-sec-30\">三十 · 硬件档位：先定 NVLink 域，再谈节点数</h3>\n<p>部署配方的第一步不是选 GPU 数量，而是确定 NVLink 域的大小。All-to-All 的时延由公式 $T_{\\text{dispatch}}=2Skd/B_{\\text{NVLink}}$ 主导，分母是链路带宽，分子是每层要搬的 token 激活量。NVLink/NVSwitch 域内，这条路径的带宽足以让 dispatch 与分组 GEMM 重叠；一旦 token 跨出域，落到 IB，带宽骤降，重叠设计失效。因此硬件档位的判断标准很直接：单层 MoE 的跨域 token 比例必须压到足够低，使 $T_{\\text{dispatch}}$ 不超过 $T_{\\text{GEMM}}$ 的同一量级。</p>\n<p>工程上把档位分成三档。第一档是单节点 8 卡全 NVLink 互联，专家并行度不超过 8，所有 dispatch 走纯 NVLink，DeepEP 低延迟模式全程生效，这是解码小 batch 最稳的形态。第二档是 GB200/GB300 NVL72 机柜级 NVLink 域，域内 rank 数可达数十，专家可以放得更散、单卡专家数更少，代价是域内 All-to-All 的 fan-in/fan-out 更大，需要 NVSwitch 承载聚合流量。第三档是跨机柜，NVLink 域被打断，必须显式约束专家放置，让高频共现的专家留在同一域内，跨域只承载少量长尾 token。</p>\n<p>一个具体判断：若某层 TopK 路由后，按目标 rank 聚合的发送缓冲显示超过约一成的 token 目标落在域外，就应调整专家放置或缩小 EP 度，而不是靠加大 IB 带宽硬扛——因为 combine 阶段还要把结果原路送回，跨域流量是双份的。硬件档位的选择因此等价于“先保证域内闭环，再考虑横向扩展”。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-31\">三十一 · 并行拓扑：EP 度、专家放置与 TP 的配比</h3>\n<p>拓扑配方要同时定三件事：专家并行度 EP、张量并行度 TP、以及专家到 rank 的映射。EP 决定 All-to-All 的参与者数量，TP 决定单个专家矩阵乘的切分方式。对解码阶段，TP 的通信是每层全量激活的 All-Reduce，EP 的通信是稀疏的按专家分桶搬运；两者叠加时，TP 组应尽量落在 NVLink 域内的小范围，EP 组可以跨更大范围但必须保持域内为主。</p>\n<p>专家放置的约束写成伪代码思路：对每个专家 $e$，统计其在校准流量下的被路由频次 $f_e$ 与共现矩阵 $C_{e,e'}$；把高 $f_e$ 且高共现的专家对分配到同一 NVLink 域，把低频专家作为跨域填充。目标是最大化域内命中的 token 比例，等价于最小化 $\\sum_t \\mathbb{1}[\\text{rank}(e_t)\\notin \\text{domain}(t)]$。这一步不需要精确求解，按频次排序做贪心装箱即可，但必须用真实路由分布校准，而非均匀假设。</p>\n<p>代价体现在显存与带宽两侧。EP 度越高，单卡承载的专家权重越少，专家权重显存压力下降，但每卡的接收缓冲与元数据缓冲随 EP 线性增长；TP 度越高，单专家矩阵被切得更细，tcgen05 分组 GEMM 的 tile 效率下降，且 All-Reduce 频次上升。解码小 batch 下，推荐让 TP 保持在域内较小范围、把扩展性交给 EP，因为 EP 搬的是被路由到的稀疏 token，而 TP 搬的是全量激活。</p>\n<p>具体例子：NVL72 域内做 EP=32、TP=2 的配比，使每个 rank 承载少量专家、单专家仍保有足够大的 GEMM tile；若把 EP 提到域外，跨域 token 比例上升，combine 的木桶效应会把整层时延拉到最慢 rank 的水平。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-32\">三十二 · 量化方案：与调度正交，但要匹配分组 GEMM 的粒度</h3>\n<p>量化与 All-to-All 调度在数据流上正交：dispatch 搬的是激活与元数据，combine 搬的是专家输出，量化改变的是 GEMM 的输入精度与权重驻留体积。但两者在粒度上耦合——分组 GEMM 按本地专家分组，若量化方案要求跨专家的统一缩放因子，就会破坏分组独立性。因此配方上应选微缩放类方案，让每个专家、每个分组块持有自己的缩放，NVFP4 权重与激活微缩放可叠加在调度之上，无需改动 All-to-All 的分桶逻辑。</p>\n<p>量化带来的系统代价要算清楚：权重从高精度压到 NVFP4，专家权重显存占用下降，使单卡能容纳更多专家，从而允许更低的 EP 度或更大的域内专家密度，间接减少跨域流量；激活侧量化则缩小 dispatch 的字节数，直接降低 $T_{\\text{dispatch}}$ 的分子 $2Skd$。但量化引入的反量化与缩放应用会增加 GEMM 前的准备开销，在解码小 batch 下这部分固定开销占比不低，需要与 dispatch 重叠窗口对齐，否则会把本可隐藏的通信时间重新暴露出来。</p>\n<p>具体做法：权重侧按专家独立校准缩放，激活侧按 token 分组做微缩放；dispatch 缓冲按量化后的字节宽度分配，元数据（目标 rank、专家 id、门控权重）保持高精度以免路由误差。KV 侧同理，分层 KV 压缩与专家权重共存于同一显存预算，量化 MoE 与 KV 策略各自独立调参，互不改写对方的布局。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-33\">三十三 · KV 策略与显存预算：把专家权重和分页 KV 放进同一本账</h3>\n<p>KV 策略在 MoE 部署里不是独立话题，它和专家权重争夺同一块 HBM。配方上先做静态划分：专家权重按 EP 度与量化精度算出每卡驻留量，剩余显存留给分页 KV 池与接收/发送缓冲。解码阶段 KV 随并发请求线性增长，而专家权重是固定成本，因此 KV 池的上限决定了可承载的并发 batch 上限，进而决定 All-to-All 的 batch 规模——batch 越小，通信固定开销占比越高，越依赖 NVLink 低延迟模式。</p>\n<p>分层 KV 的思路是把热层 KV 留在 HBM、冷层下沉，从而给专家权重和通信缓冲腾出空间。代价是冷层访问引入额外时延，且下沉/回迁的时机要与连续批处理的调度节拍对齐，否则会在 decode 步内插入同步点，破坏 dispatch 与 GEMM 的重叠。工程判断是：当 KV 池接近上限、batch 被迫缩小时，优先做 KV 压缩或分层，而不是降 EP 度——降 EP 度会把更多专家压到单卡，反而恶化 GEMM 的 tile 效率。</p>\n<p>具体例子：给定每卡 HBM 预算，先扣掉 NVFP4 专家权重与收发缓冲，余量按每 token 每层 KV 字节数反推最大并发 token 数；若该数低于目标并发，则启用分层 KV 把冷层移出，保持 batch 规模不塌陷，使 All-to-All 始终运行在固定开销可被重叠吸收的区间。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-34\">三十四 · 调度参数：容量因子、重叠窗口与超时</h3>\n<p>调度参数决定重叠能否真正生效。核心参数有三类：路由容量因子（每专家接收 token 上限）、dispatch 与 GEMM 的重叠窗口划分、以及 combine 的等待策略。容量因子过小会触发令牌丢弃，改变实际搬运量；过大则让慢专家拖长 GEMM。配方上应让容量因子与专家放置的频次校准联动——高频专家给足容量，低频专家收紧，使各 rank 的 GEMM 工作量接近均衡，削弱 combine 的木桶效应。</p>\n<p>重叠窗口的划分写成思路：把一层拆为 dispatch 分块发送、接收端按到达的专家分组即时启动 tcgen05 分组 GEMM、combine 在本地专家全部完成后立即回送。关键是接收端不能等全量 dispatch 结束才开算，否则退化为“先全量 dispatch 再串行 GEMM”的朴素实现。调度器需要暴露“某专家分组的 token 已到齐”这一事件作为 GEMM 启动条件，事件粒度越细，重叠越充分，但事件管理本身有开销，需与分组大小折中。</p>\n<p>代价与失败模式：combine 必须等所有专家 rank 完成，最慢 rank 决定整层时延；若某 rank 因容量因子溢出或 GEMM tile 不佳而变慢，整条流水停顿。调度参数应设置每层 combine 的等待上限与降级路径，避免单 rank 抖动放大为全局停顿。另一个失败模式是小 batch 误走 IB：调度器必须显式判断目标 rank 是否在 NVLink 域内，域内一律走低延迟路径，不得因缓冲策略回落到 IB。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-35\">三十五 · 可复现的配置思路：从校准到压测的闭环</h3>\n<p>把上述五块串成可复现流程。第一步，用真实请求分布跑一次路由校准，得到专家频次与共现矩阵，据此定专家放置与 EP 度，确保域内 token 比例达标。第二步，按量化精度算专家权重驻留量，扣减后定 KV 池上限与最大并发 token 数，必要时启用分层 KV。第三步，按并发规模选调度参数：容量因子按频次分配，重叠窗口按专家分组粒度切分，combine 设等待上限。第四步，压测时分别观测 $T_{\\text{dispatch}}$、$T_{\\text{GEMM}}$、$T_{\\text{combine}}$ 三段，确认 $\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})+T_{\\text{combine}}$ 中通信项不占主导；若占主导，先查跨域比例，再查是否误走 IB，最后查容量因子是否造成 rank 间不均衡。</p>\n<p>这套流程的判据是单 token 时延（TPOT）而非吞吐：解码阶段 SLO 以 TPOT 为主，任何使最慢 rank 变慢的参数都应回退。配置的复现性来自固定校准集与固定放置算法，使每次部署的域内命中率与 rank 负载分布可比。最终落在一条工程判断上：All-to-All 调度的配方本质是把“跨域比例”和“最慢 rank”这两个量压到重叠窗口能吸收的范围，硬件档位、拓扑、量化、KV、调度参数都只是围绕这两个量的调节旋钮。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-36\">三十六 · 配方落地时的失效边界：从拓扑约束到慢 rank 木桶</h3>\n<p>这套配方的前提是专家放置与 NVLink 域边界对齐：把每个专家的全部副本约束在同一 NVSwitch 域内，dispatch 走纯 NVLink All-to-All，只有 token 的原 rank 与目标专家 rank 跨域时才回落 IB。一旦 router 的热度分布偏移——某个专家在解码 batch 中被高频命中，而它的副本被放在域外——跨域流量按 <span class=\"formula\">$$T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</span> 的分子项（token 数 S、TopK 数 k、隐藏维 d）线性放大，但分母换成远低于 NVLink 的 IB 带宽，dispatch 项迅速超过 GEMM 项，重叠设计退化为串行等待。工程判断是：专家放置必须按在线 router 统计的命中率做加权，而不是按参数均匀切分；域内 rank 数越多，重叠收益越明显，但跨域比例一旦上升，收益被 All-to-All 延迟吞掉。</p>\n<p>第二个失效条件是 combine 的木桶效应。combine 必须等所有专家 rank 完成本地分组 GEMM 才能汇总，整层时延由最慢 rank 决定，而不是平均 rank。若某 rank 因专家负载不均或 TMEM 占用过高而落后，其余 rank 的 dispatch 缓冲只能空转，流水线出现周期性停顿。可复现的配置思路是在调度参数里给每个 rank 设专家容量上限与 token 溢出阈值，溢出 token 走备用副本而非排队等待，把最慢 rank 的尾延迟压到与中位 rank 同一量级；代价是备用副本带来额外显存占用与一次额外的 combine 跳数。</p>\n<p>第三是小 batch 下的路径误判。解码阶段 batch 内 token 少、每 token 仅激活 TopK 个专家，通信固定开销占比高；若运行时因拓扑探测失败或专家副本缺失而误走 IB，固定开销直接吃掉重叠窗口，DeepEP 低延迟模式在 NVLink 域内的收益归零。配方中应把“NVLink 域内纯 NVLink 路径”作为硬约束写入调度器，跨域请求在准入阶段就被拒绝或改派，而不是在 dispatch 时才回落。量化与 KV 压缩与该调度正交，可叠加 NVFP4 权重与分层 KV，但它们不改变上述边界：显存节省换来更大 batch，反而可能让专家热度更集中，放大放置不均的风险。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发信号</th><th>系统代价</th></tr></thead><tbody><tr><td>专家副本跨域</td><td>域外命中率上升</td><td>dispatch 项被 IB 带宽主导，TPOT 抬升</td></tr><tr><td>慢 rank 拖尾</td><td>combine 等待时间方差变大</td><td>整层时延由最慢 rank 决定，吞吐下降</td></tr><tr><td>小 batch 误走 IB</td><td>固定开销占比过高</td><td>重叠窗口失效，通信与 GEMM 串行</td></tr></tbody></table>\n<h3 id=\"alg-moe-alltoall-ep-sec-37\">三十七 · 层时延的加性分解：谁在关键路径上</h3>\n<p>把 MoE 层在解码阶段的时间拆开看，关键路径只有三段：dispatch、分组 GEMM、combine。三者不是并行关系，而是“通信—计算—通信”的串联骨架，重叠只发生在 dispatch 与 GEMM 之间。因此层时延可以写成</p>\n<div class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</div>\n<p>这里 $S$ 是 batch 内 token 数，$k$ 是 TopK，$d$ 是隐藏维，系数 2 表示 dispatch 与 combine 各搬一次等价载荷。这个式子的工程含义是：<strong>combine 永远在关键路径上，无法被隐藏</strong>。dispatch 再快，只要 combine 没完成，本层就不能写回激活缓冲，下一层也就无法启动。于是优化 dispatch 只能把 $T_{\\text{layer}}$ 压到 $T_{\\text{GEMM}}+T_{\\text{combine}}$ 的下界，而 combine 的时延由最慢 rank 决定，不由平均带宽决定。</p>\n<p>小 batch 解码时 $S$ 很小，$T_{\\text{GEMM}}$ 被 tcgen05 分组 GEMM 压得很低，此时 $T_{\\text{dispatch}}$ 的固定开销（建桶、元数据打包、NVLink 事务启动）占比反而上升。DeepEP 低延迟模式的价值就在这里：它把 dispatch 从小 batch 下的“带宽受限”转成“固定开销受限”，在 NVLink 域内避免回落 IB，使 $\\max$ 项不至于被通信吃掉。代价是这条路径只在 NVLink 域内成立，一旦 token 需要跨节点，$B_{\\text{NVLink}}$ 被替换成远低的 IB 带宽，$T_{\\text{dispatch}}$ 立刻反超 $T_{\\text{GEMM}}$，重叠设计失效。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-38\">三十八 · 显存的三份账：激活、发送缓冲、专家权重</h3>\n<p>All-to-All 调度在显存上要同时付三笔账，且它们互相挤占。第一笔是 token 激活与元数据：dispatch 前需要按目标 rank 聚合的发送缓冲，其大小与 $S\\cdot k\\cdot d$ 成正比，还要为每个 token 携带目标专家索引与门控权重。第二笔是接收端的按专家分组缓冲，接收到的 token 要按本地专家重排后才能喂给分组 GEMM，重排本身需要一块临时区。第三笔是专家权重常驻显存——这部分与分页 KV 共享同一显存池，专家权重越大，留给 KV 页的空间越小，连续批处理的并发度就被压缩。</p>\n<p>三笔账的冲突在解码阶段最尖锐：解码的 KV cache 随并发请求线性增长，而专家权重是固定占用。当专家并行度提高、单卡只放少量专家时，单卡权重占用下降，但发送/接收缓冲随跨 rank token 数上升。工程判断是：<strong>发送缓冲应按峰值 token 数预分配并复用，不能按请求动态申请</strong>，否则分配器碎片会在长稳态服务中累积成尾延迟抖动。代价体现在并发上限上：缓冲预留越多，可容纳的 KV 页越少，batch 上限下降，吞吐随之下降——这是一条显存换吞吐的硬约束曲线。</p>\n<p>具体例子：一个 TopK=8 的解码 batch，若专家分散在 NVLink 域内多个 rank，每个 token 的激活需要被复制到最多 8 个目标 rank 的发送槽。若缓冲按“每 token 每目标专家一格”静态预留，缓冲占用就是 $S\\times k$ 格而非 $S$ 格，显存放大倍数等于 $k$。这就是为什么调度层必须与容量因子路由协同——路由侧少发一点，缓冲侧就少一格。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-39\">三十九 · 带宽的两个域：NVLink 域内与跨节点 IB</h3>\n<p>All-to-All 的带宽代价不是单一数字，而是按域分层。NVLink/NVSwitch 域内，dispatch 走纯 NVLink 路径，带宽高、固定开销低；跨节点则回落 IB，带宽远低于 NVLink。于是整层的有效带宽取决于<strong>跨域流量占比</strong>，而不是链路峰值。设跨域 token 比例为 $\\rho$，则有效 dispatch 时间近似为</p>\n<div class=\"formula\">$$T_{\\text{dispatch}}\\approx(1-\\rho)\\frac{2Skd}{B_{\\text{NVLink}}}+\\rho\\frac{2Skd}{B_{\\text{IB}}}$$</div>\n<p>由于 $B_{\\text{IB}}\\ll B_{\\text{NVLink}}$，即使 $\\rho$ 只有很小的值，第二项也会主导。这就是“规模上去以后哪里先崩”的第一个答案：<strong>先崩的不是算力，是跨域比例</strong>。专家放置不当会把原本域内的 token 推到跨节点路径上，$\\rho$ 上升，$T_{\\text{dispatch}}$ 迅速吞掉重叠收益。规模扩张时，NVLink 域大小是硬边界——域内 rank 越多，可容纳的专家越多，$\\rho$ 越低；一旦专家数超过域内容量，跨域流量不可避免。</p>\n<p>代价还体现在 combine 上：combine 把专家输出送回原 token 所在 rank，其流量结构与 dispatch 对称，同样受 $\\rho$ 支配。区别在于 combine 不能被隐藏，所以跨域 combine 的时延直接加到关键路径末端。工程上因此有一条放置约束：<strong>把高流量专家约束在 NVLink 域内，把长尾专家放到跨域位置</strong>，用路由侧的容量因子把跨域 token 压到可控比例。这与分离式专家并行的拓扑选择是同一枚硬币的两面。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-40\">四十 · 通信与计算的流水：重叠窗口有多宽</h3>\n<p>重叠的本质是让 dispatch 的传输与分组 GEMM 的计算在时间上交错。伪代码思路是：接收端不必等全部 token 到齐才开始算，而是按专家分桶、桶满即启动该专家的 tcgen05 分组 GEMM，同时后续桶仍在传输。</p>\n<ul>\n<li>router 产出映射，按目标 rank 聚合发送缓冲；</li>\n<li>dispatch 分块发出，接收端按本地专家入桶；</li>\n<li>某专家桶达到阈值即 launch 分组 GEMM，与剩余传输并行；</li>\n<li>combine 在全部专家 GEMM 完成后启动，按原 token 位置加权求和。</li>\n</ul>\n<p>重叠窗口的宽度受两个因素限制。其一是<strong>最慢 rank</strong>：combine 必须等所有专家 rank 完成，任一 rank 的 GEMM 或接收延迟都会拖住整层，形成木桶效应。其二是<strong>桶粒度</strong>：桶太小则 GEMM launch 开销占比高，桶太大则重叠窗口变窄、尾部等待变长。工程判断是桶粒度应随 $S$ 自适应——小 batch 解码用细桶换重叠，大 batch 预填用粗桶换 GEMM 效率。</p>\n<p>代价是流水线空转的量化：若 dispatch 与 GEMM 完全串行，层时延为 $T_{\\text{dispatch}}+T_{\\text{GEMM}}+T_{\\text{combine}}$；完全重叠时为 $\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})+T_{\\text{combine}}$。两者之差就是重叠收益，它正比于 $\\min(T_{\\text{dispatch}},T_{\\text{GEMM}})$。当 $T_{\\text{dispatch}}$ 因跨域而膨胀到远超 $T_{\\text{GEMM}}$ 时，$\\max$ 退化为 $T_{\\text{dispatch}}$，重叠收益归零——这正是规模上去后第二个崩点：<strong>重叠窗口被跨域带宽压扁</strong>。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-41\">四十一 · 尾延迟与功耗：木桶效应与固定开销</h3>\n<p>解码服务的 SLO 以单 token 时延（TPOT）为主，而 TPOT 的分布由尾延迟决定，不由均值决定。All-to-All 的尾延迟来源有三：最慢 rank 的 combine 等待、跨域 token 的 IB 往返、以及小 batch 下误走 IB 路径导致的固定开销占比过高。三者叠加时，P99 会显著偏离 P50，而容量规划若按均值算并发，就会在尾延迟上违约。</p>\n<p>功耗侧的代价是隐性的：All-to-All 期间 GPU 的 GEMM 单元并非满载，通信引擎与 SM 的功耗配比改变。重叠设计让 GEMM 与传输同时活跃，单卡功耗上升但单位 token 能耗下降；反之串行执行时，通信段 SM 空转，功耗花在搬运而非计算上，能效比恶化。规模扩张后，跨域流量占比上升，能耗结构从“计算主导”转向“搬运主导”，这是容量规划必须计入的一项。</p>\n<p>具体例子：一个 NVLink 域内 rank 数刚好容纳全部专家的部署，$\\rho$ 接近零，combine 等待仅由 GEMM 完成时间差决定，尾延迟可控；一旦专家数超出域内容量，部分专家落到跨节点，$\\rho$ 抬升，combine 的关键路径上出现 IB 往返，P99 TPOT 被拉长，此时扩容反而恶化 SLO——规模上去后第三个崩点：<strong>尾延迟先于吞吐崩</strong>。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-42\">四十二 · 规模扩张的崩点排序与工程判断</h3>\n<p>把五个代价维度按“先崩顺序”排：第一是跨域比例 $\\rho$，它直接放大 $T_{\\text{dispatch}}$ 与 $T_{\\text{combine}}$；第二是 combine 的最慢 rank，木桶效应随 rank 数增加而放大方差；第三是显存三份账的挤占，缓冲预留压缩 KV 页、压低并发；第四是重叠窗口被压扁后流水线空转；第五才是功耗与能效。这个排序的工程含义是：扩容时先检查专家放置是否越出 NVLink 域，再检查 combine 的 rank 间方差，最后才看显存与功耗。</p>\n<table class=\"mini\"><thead><tr><th>代价维度</th><th>主导因素</th><th>规模扩张时的行为</th><th>工程对策</th></tr></thead><tbody><tr><td>dispatch 带宽</td><td>跨域比例 $\\rho$</td><td>$\\rho$ 微升即主导时延</td><td>专家约束在 NVLink 域内</td></tr><tr><td>combine 尾延迟</td><td>最慢 rank</td><td>rank 数增，方差放大</td><td>桶粒度自适应、负载均衡</td></tr><tr><td>显存</td><td>缓冲预留 vs KV 页</td><td>并发上限被压缩</td><td>缓冲静态复用、容量因子路由</td></tr><tr><td>重叠窗口</td><td>$\\min(T_{\\text{dispatch}},T_{\\text{GEMM}})$</td><td>跨域后收益归零</td><td>细桶换重叠、低延迟模式</td></tr><tr><td>功耗</td><td>搬运/计算配比</td><td>能效比恶化</td><td>减少跨域搬运</td></tr></tbody></table>\n<p>判断落在一条具体机制上：<strong>把专家放置当作一等约束，而不是事后调优</strong>。部署时先按 NVLink 域容量确定专家并行度上限，再用容量因子路由把溢出 token 的跨域比例压到重叠窗口仍能吸收的水平；combine 侧用桶粒度与 rank 间负载均衡压方差。规模上去以后先崩的是跨域比例与 combine 木桶，而不是算力或显存——扩容的正确姿势是扩域，不是扩 rank。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-43\">四十三 · 规模放大后先崩的三条线：跨域流量、combine 木桶与功耗墙</h3>\n\n<p>把专家并行推到多节点后，第一个失效点不是算力而是拓扑。层时延由 <span class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</span> 刻画，其中 $S$ 为 batch 内 token 数、$k$ 为 TopK、$d$ 为隐维、$B_{\\text{NVLink}}$ 为域内有效带宽。重叠设计只能隐藏 $\\max$ 里的较小项，一旦专家放置使部分 token 落到 NVLink 域外、dispatch 回落到 IB，$B$ 骤降而 $T_{\\text{dispatch}}$ 抬升，$\\max$ 立刻由 GEMM 翻转为通信主导——解码阶段 TPOT 被跨域搬运吃掉，重叠收益归零。工程判据很直接：统计每层 dispatch 流量中跨域 token 占比，占比越过某个门槛后，加卡不再降时延反而抬尾延迟。DeepEP 低延迟模式的价值恰在此处——小 batch 解码时它把路径锁在 NVLink 域内、绕开 IB 固定开销，但这一前提是专家放置本身不越域。</p>\n\n<p>第二个失效点是 combine 的同步屏障。combine 必须等本层所有专家 rank 完成分组 GEMM 才能回送，整层时延由最慢 rank 决定，形成木桶效应：某个 rank 因专家承载 token 偏多、或 tcgen05 分组 GEMM 因分组粒度碎片化而利用率下降，就会拖住全层。这与 dispatch 侧的可重叠性不对称——dispatch 能藏进 GEMM，combine 却天然串行在尾部，尾延迟随 rank 数放大而非收敛。缓解手段是让 router 的负载在专家间更均匀（容量因子与 token 丢弃/重路由策略），并把分组 GEMM 的 tile 划分对齐本地专家数，减少小分组带来的 MMA 空转；但任何均衡都只是把最慢 rank 的尖峰削平，不能消除屏障本身。</p>\n\n<table class=\"mini\"><thead><tr><th>代价维度</th><th>域内 NVLink 方案</th><th>跨域 IB 回落</th></tr></thead><tbody><tr><td>dispatch 时延</td><td>随 $S\\cdot k\\cdot d$ 线性、可被 GEMM 隐藏</td><td>带宽低一个档，$\\max$ 翻转为通信主导</td></tr><tr><td>combine 尾延迟</td><td>受最慢 rank 约束</td><td>跨域回送叠加同步屏障，尾延迟倍增</td></tr><tr><td>显存</td><td>发送/接收缓冲按 token 分桶驻留</td><td>跨域缓冲需双份驻留、挤占 KV 空间</td></tr><tr><td>功耗</td><td>NVSwitch 与域内链路功耗可控</td><td>IB 网卡与光模块在解码空转期持续耗电</td></tr></tbody></table>\n\n<p>第三个失效点是显存与功耗的耦合。dispatch/combine 需要按目标 rank 分桶的发送与接收缓冲，token 元数据与激活都要在域内多跳驻留；规模上去后这部分缓冲与 KV cache 争抢 HBM，尤其在长上下文解码时，KV 压缩（分层 KV、NVFP4 权重）虽与该调度正交可叠加，但缓冲膨胀会先吃掉压缩省下的空间。功耗侧，跨域 IB 网卡与光模块在解码小 batch 的低利用率窗口里持续耗电，能效比随跨域比例恶化。真正的工程判断是：专家并行 All-to-All 的规模上限由 NVLink 域大小与 IB 带宽共同锁定，扩域之前先做专家放置的域内约束与 combine 尾延迟治理，否则加节点只会把瓶颈从 GEMM 搬到网络。</p>\n<h3 id=\"alg-moe-alltoall-ep-sec-44\">四十四 · 精度漂移：从 dispatch 元数据到 combine 加权</h3>\n<p>MoE 层的数值错误很少来自 GEMM 本身，而多半来自 All-to-All 往返过程中元数据与激活的对齐。dispatch 阶段每个 token 携带目标专家索引、门控权重 $g_{t,e}$ 和原位置槽号；combine 阶段按槽号把专家输出写回。一旦接收端按本地专家分组时排序与发送端不一致，或者槽号在跨 rank 重排中丢失，就会出现“权重乘错 token”的静默错误——输出数值仍在合理范围内，但语义已经错位。这类问题在小 batch 解码时尤其隐蔽，因为单步只有几十个 token，误差被后续层稀释，表现为生成质量缓慢退化而非崩溃。</p>\n<p>诊断手段是把 $y_t=\\sum_{e\\in\\mathrm{TopK}(t)} g_{t,e}\\,\\mathrm{GEMM}_e(x_t)$ 拆成可核对的中间量：在 dispatch 缓冲区里保留 token 的全局唯一 id，接收端计算完成后按 id 回填，并在 combine 前插入一次校验——比较本地累加的门控权重之和与 router 输出的 TopK 权重之和，偏差超过阈值即标记该 token。工程上更省的做法是让元数据与激活走同一条 All-to-All，用同一份缓冲区布局，避免两条通道的排序逻辑分叉。代价是每个 token 多带若干字节元数据，在 NVLink 域内这部分带宽开销可忽略，但跨 IB 时会放大固定开销，因此校验开关应做成按部署拓扑可配。</p>\n<p>具体例子：某解码服务在启用专家选择路由后出现长尾回答重复，排查发现是 combine 阶段按专家分组顺序回填而非按原槽号回填，TopK=2 时两个专家的输出被交换加权。修复方式是在接收缓冲中显式保存槽号数组，combine 内核按槽号散射写回。这类 bug 不会触发任何硬件异常，只能靠端到端的 token id 追踪定位。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-45\">四十五 · OOM：分页 KV 与专家权重的地址空间争抢</h3>\n<p>专家并行部署里，OOM 通常不是单点显存不足，而是分页 KV cache 的块分配与专家权重常驻之间发生碎片化争抢。解码阶段每步新增 KV 块，块表增长是渐进的；而专家权重在 All-to-All 调度下要求每个 rank 常驻自己负责的专家，权重占用是刚性的。当并发请求数上升，KV 块分配器不断向高地址扩张，与专家权重的预留区间碰撞，表现为“显存还有余量但分配失败”。</p>\n<p>监控要点是分别跟踪三块水位：专家权重常驻区、KV 块池的空闲块数、dispatch/combine 收发缓冲的峰值占用。收发缓冲随 batch 内 token 数与跨 rank 比例变化，最慢 rank 的缓冲峰值往往决定整层能否启动。一个可操作的判据是：当空闲 KV 块数低于单步解码所需块数的若干倍时，提前触发请求排队而非等到分配失败，把 OOM 转成可控的准入延迟。</p>\n<p>回滚路径上，最有效的手段是降低专家并行的跨域比例——把专家放置约束回 NVLink 域内，减少跨节点缓冲；其次是收紧每 rank 的专家数上限，用更多 rank 分摊权重。代价直接体现在吞吐：专家数分摊越细，单 rank 的分组 GEMM 规模越小，tcgen05 的利用率下降，解码 TPOT 变长。因此 OOM 处置不是单纯扩容，而是在显存、跨域流量与计算效率之间重新取点。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-46\">四十六 · 批抖动与路由不均：容量因子之外的真实分布</h3>\n<p>批抖动指相邻解码步之间 batch 内 token 数剧烈变化，导致 All-to-All 的发送缓冲尺寸和分组 GEMM 的专家分组规模同步跳变。连续批处理下，新请求涌入与旧请求完成会在同一时刻发生，若调度器按固定窗口聚合，某些步的 token 数可能是均值的数倍，dispatch 时间 $T_{\\text{dispatch}}=2Skd/B_{\\text{NVLink}}$ 随 $S$ 线性上升，而 GEMM 时间上升更缓，于是 $T_{\\text{layer}}=\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})+T_{\\text{combine}}$ 中的 max 项从计算侧翻转到通信侧。</p>\n<p>路由不均则是另一层：即使总 token 数稳定，router 输出的专家分布也可能高度偏斜，热门专家所在 rank 的接收缓冲膨胀，冷门 rank 空转。容量因子路由与令牌丢弃能削平这一偏斜，但代价是丢弃 token 带来的质量损失，且丢弃比例本身随输入分布漂移。诊断上应持续采集每 rank 的接收 token 数直方图与每专家的负载熵，当熵值持续走低时说明路由在收敛到少数专家，此时扩容专家数或调整负载均衡损失比调容量因子更对症。</p>\n<p>具体例子：某服务在长上下文请求混入短请求后出现周期性 TPOT 尖刺，监控显示尖刺步的 dispatch 缓冲峰值是均值的数倍，且集中在少数几个 rank。定位为调度器把长请求的预填块与解码步混排，导致单步 token 数突增。处置是把分块预填与解码 piggyback 的节奏解耦，让预填块在独立窗口推进，解码步维持稳定 batch。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-47\">四十七 · 尾延迟尖刺：木桶效应与最慢 rank</h3>\n<p>combine 阶段必须等所有专家 rank 完成，整层时延由最慢 rank 决定。这条木桶约束在稳态下被重叠设计掩盖，但在尖刺场景下暴露：任一 rank 因接收缓冲溢出、分组 GEMM 尾块不规则、或跨 IB 回落而变慢，其余 rank 全部在 combine 屏障上空等。尖刺的传播性很强——一个慢 rank 拖慢一步，下一步的缓冲又因积压而更大，形成正反馈。</p>\n<p>监控应把每 rank 的 dispatch 完成时刻、GEMM 完成时刻、combine 到达时刻分别打点，计算 rank 间的时间差分布。判据是：当某 rank 的 GEMM 完成时刻相对中位数的偏移持续超过单层预算的固定比例时，标记为慢 rank 并触发专家迁移评估。另一个信号是跨域流量占比——若某 rank 的入站 token 中跨 IB 比例异常升高，说明专家放置已经偏离 NVLink 域约束，这正是失败模式里“专家放置不当放大跨节点 IB 流量”的直接体现。</p>\n<p>缓解手段包括：把热门专家复制到多个 rank 做读复制以摊薄单 rank 负载；在 combine 前对慢 rank 做超时降级，允许其余 rank 先写回部分结果；以及在小 batch 下强制走纯 NVLink 低延迟模式，避免误走 IB 带来的固定开销。每种手段都有代价：专家复制增加权重显存占用，超时降级牺牲部分 token 的完整性，强制 NVLink 路径限制拓扑规模。工程判断的依据是尖刺频率与 SLO 余量的比值，而非单次尖刺的绝对幅度。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-48\">四十八 · 监控面与回滚顺序</h3>\n<p>可观测性要覆盖四个层面：拓扑层记录专家到 rank 的放置表与 NVLink/IB 域边界；流量层记录每 rank 的收发 token 数、跨域比例、缓冲峰值；计算层记录分组 GEMM 的分组数与尾块效率；端到端层记录 TPOT 分位数与丢弃率。这四层对齐后才能把“TPOT 变差”快速归因到放置、路由还是缓冲。</p>\n<p>回滚应按代价从低到高排序，而不是按现象直觉。第一步回滚调度参数：收紧容量因子、降低单步最大 token 数，把批抖动压回稳定区间，代价是吞吐下降但语义不变。第二步回滚路由策略：从专家选择路由退回容量因子路由，恢复负载均衡但引入丢弃。第三步回滚放置：把跨域专家迁回 NVLink 域内，代价是单 rank 专家数上升、显存压力增大。第四步才是回滚并行度，缩小专家并行规模，这会让单卡权重膨胀，通常作为最后手段。</p>\n<p>每次回滚都必须伴随一次精度校验，因为放置与路由的变更会改变 combine 的槽号映射路径，前述静默错位最易在回滚窗口内被引入。把 token id 追踪与门控权重和校验做成常开的轻量钩子，比事后排查便宜得多。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-49\">四十九 · 工程判断：把失败模式变成准入条件</h3>\n<p>这些失败模式的共同点是它们都在稳态监控里不可见，只在边界条件下爆发。因此更稳的做法是把它们前置成准入条件：部署时校验专家放置表是否全部落在 NVLink 域内，若不满足则拒绝启动跨域配置；运行时校验每步 dispatch 缓冲峰值是否超过预留上限，超过则拒绝该批进入而非冒险分配；路由熵低于阈值时主动告警而非等待尾延迟出现。准入条件把不可控的尖刺转成可控的拒绝，代价是短时的请求排队，换来的是 TPOT 分布的收敛。</p>\n<p>最终落在具体机制上：All-to-All 调度的稳定性不取决于单个内核的优化，而取决于 dispatch 缓冲、专家放置表、combine 屏障三者是否在同一套约束下协同。把这三者的水位与边界做成可观测、可准入、可回滚的闭环，才能让重叠设计在真实负载下持续兑现收益，而不是在尖刺与 OOM 之间反复震荡。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-50\">五十 · 失效边界：从木桶效应到跨域回退</h3>\n<p>这套调度方案的上限由 NVLink 域尺寸与 IB 带宽共同锁定，一旦专家放置越出域边界，公式里的 $T_{\\text{dispatch}}$ 就不再由 NVLink 决定，而由跨节点 IB 链路接管：$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$ 分子中的 $S$（本层 token 数）、$k$（TopK）、$d$（隐藏维）在解码小 batch 下并不大，真正致命的是分母从 NVLink 带宽跌到 IB 带宽后，dispatch 项直接压过分组 GEMM，重叠设计失去可隐藏的对象。诊断上应把每个 MoE 层的 dispatch 字节按目标 rank 分桶统计，若某 rank 的入向流量中跨域占比持续偏高，说明 router 的专家亲和性与物理放置已经错位——这是精度问题之外最隐蔽的精度退化源：门控权重本身没错，但 token 被搬到了错误的域，尾延迟随之抬升。</p>\n<p>第二个失效点是 combine 的同步语义。combine 必须等所有专家 rank 完成本地分组 GEMM 才能归约，整层时延由最慢 rank 决定，形成木桶效应：某个 rank 因专家承载 token 数偏多而 GEMM 排队，其余 rank 的 NVLink 链路空转。这与路由不均直接耦合——router 在小 batch 下方差极大，少数专家吸走大部分 token，对应 rank 的 tcgen05 分组 GEMM 被拉长，而其他 rank 早已算完在等。监控应采集每 rank 的 token 计数分布与 GEMM 占用率，把“最慢 rank 的 GEMM 时间 / 平均 GEMM 时间”作为抖动指标；该比值随 batch 减小而放大，是批抖动的直接来源。</p>\n<p>第三类是 OOM 与回滚。All-to-All 的发送/接收缓冲按最坏情况预分配，专家放置调整后缓冲尺寸与元数据表都要重算；若沿用旧配置，接收端按本地专家分组时会出现缓冲越界或显存峰值抬升。回滚路径应绑定在专家放置拓扑这一层：把 rank 到专家的映射表做成可版本化配置，异常时回退到上一版放置并强制走 NVLink 域内路径，而不是回退到逐专家独立 launch 的朴素实现——后者会把通信与计算重新串行化，代价是整层时延回到未重叠水平。工程判断是：先降跨域比例，再谈重叠收益；跨域占比未压下去之前，任何 dispatch-GEMM 重叠都只是在给 IB 延迟做陪跑。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>专家放置越域</td><td>rank 入向流量跨域占比</td><td>dispatch 主导，TPOT 抬升</td></tr><tr><td>路由不均</td><td>最慢/平均 GEMM 时间比</td><td>combine 木桶停顿</td></tr><tr><td>小 batch 误走 IB</td><td>通信固定开销占比</td><td>重叠失效，尾延迟尖刺</td></tr></tbody></table>\n<h3 id=\"alg-moe-alltoall-ep-sec-51\">五十一 · 选型的第一性问题：把\"搬运谁\"钉死</h3>\n<p>同族算法在 MoE 解码上的分歧，本质不是实现细节之争，而是\"每一层要搬多少字节、搬给谁\"的差异。All-to-All 专家并行搬的是被路由命中的 token 激活及其元数据，搬运量正比于 <span class=\"inline-math\">S·k·d</span>（token 数 × TopK × 隐维）；张量并行搬的是全量激活的切分片，与路由无关；专家复制/冗余部署则把搬运量压到零但用显存换。选型时先问一句：本层激活的稀疏度 <span class=\"inline-math\">k/E</span> 是多少？稀疏度低（TopK 占比高、专家总数少），All-to-All 的搬运量接近全量激活，收益被通信吃掉，此时纯 TP 或 TP+EP 混合更划算；稀疏度高（细粒度专家、TopK 小），按 token 稀疏搬运才真正省带宽。这一步判断做完，后面的决策表才有意义。</p>\n<div class=\"formula\">$$\\text{搬运比}=\\frac{2\\,S\\,k\\,d}{2\\,S\\,d}=\\frac{k}{E_{\\text{local}}}$$</div>\n<p>搬运比的分母是 TP 情形下每卡需接收的全量激活分片。当 <span class=\"inline-math\">\\(k/E_{\\text{local}} &lt; 1\\)</span> 时 All-to-All 在字节数上占优；但字节数占优不等于时延占优——All-to-All 是\"多对多\"的散射模式，其固定开销（建桶、元数据、同步栅栏）在小 batch 下不可忽略，而 TP 的集合通信是规整的环/树，固定开销更低。这就是为什么小 batch 解码必须走 NVLink 域内的低延迟模式，否则字节优势会被固定开销抹平。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-52\">五十二 · 决策表：五个维度的交叉判定</h3>\n<p>把选型拆成可判定的维度，避免\"看情况\"式的模糊建议。下表以工程可观测量为行，给出同族算法的适用条件；表中不写具体带宽与延迟数字，因为材料未给出，只保留定性排序。</p>\n<table class=\"mini\"><thead><tr><th>判定维度</th><th>All-to-All EP（本条目）</th><th>张量并行 TP</th><th>专家复制/冗余</th><th>分离式 EP</th></tr></thead><tbody><tr><td>激活稀疏度</td><td>高（k/E 小）</td><td>无关</td><td>高</td><td>高</td></tr><tr><td>batch 规模</td><td>小 batch 解码为主</td><td>大 batch 更划算</td><td>小 batch</td><td>预填/解码分离后各自最优</td></tr><tr><td>跨域比例</td><td>必须低，约束在 NVLink 域</td><td>可跨节点但代价高</td><td>无跨域搬运</td><td>跨域流量集中在预填侧</td></tr><tr><td>显存余量</td><td>需容纳全量专家权重</td><td>权重切分，显存友好</td><td>需冗余权重，显存最紧</td><td>两侧各自容纳所需分片</td></tr><tr><td>木桶效应敏感度</td><td>高（combine 等最慢 rank）</td><td>中（集合通信同步）</td><td>低</td><td>中</td></tr></tbody></table>\n<p>读表方式：先看\"激活稀疏度\"与\"batch 规模\"两行定主选，再用\"跨域比例\"与\"显存余量\"做否决项。若跨域比例高且无法通过专家放置收敛到 NVLink 域内，All-to-All EP 的重叠收益会被 IB 延迟吞掉，此时应退回 TP 或改为专家复制；若显存不足以容纳全量专家权重，All-to-All EP 直接出局，因为它的前提就是每卡持有本地专家全集。木桶效应一行是稳定性判据：combine 必须等所有 rank，任一慢 rank 拖住整层，因此当集群存在异构卡或网络抖动时，All-to-All EP 的尾延迟风险高于 TP。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-53\">五十三 · 与容量因子路由、专家选择路由的接口关系</h3>\n<p>All-to-All 调度不是孤立算法，它的输入由路由层决定，输出由分组 GEMM 消费。容量因子路由通过截断每专家接收的 token 数来限制单 rank 的接收缓冲上界，从而把 dispatch 的桶大小变成可预算量；专家选择路由则反向——让专家挑 token，天然产生更均衡的每 rank 负载，减少 combine 阶段的木桶效应。选型时若路由侧已采用专家选择，All-to-All 的负载不均衡风险下降，可以放宽对专家放置的约束；若采用容量因子路由并伴随令牌丢弃，则 dispatch 缓冲可预估，重叠窗口更容易排布，但丢弃率上升会改变有效稀疏度，进而影响第一节的搬运比判断。这两者是本算法的上游约束，具体机制见对应条目，此处只保留接口结论：路由策略决定 All-to-All 的桶上界与均衡度，二者必须联合选型，不能各自最优。</p>\n<div class=\"formula\">$$T_{\\text{layer}}=\\max\\left(T_{\\text{dispatch}},\\,T_{\\text{GEMM}}\\right)+T_{\\text{combine}},\\quad T_{\\text{dispatch}}=\\frac{2\\,S\\,k\\,d}{B_{\\text{NVLink}}}$$</div>\n<p>公式给出选型的量化抓手：<span class=\"formula-inline\">T_dispatch</span> 与 <span class=\"formula-inline\">T_GEMM</span> 的相对大小决定重叠是否有意义。若 dispatch 远大于 GEMM，重叠后整层仍由通信主导，说明该配置下专家放置或 batch 规模不适配，应改用 TP 或缩小 NVLink 域；若 GEMM 远大于 dispatch，重叠收益接近上限，此时应把优化预算转向 GEMM 侧（量化、融合大核）而非继续压通信。工程上可在 profiler 里直接读这两个分量，作为是否维持 All-to-All 的判据。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-54\">五十四 · 与分离式部署、投机解码的组合边界</h3>\n<p>分离式预填/解码把长预填与短解码拆到不同资源池，All-to-All 的适用面随之变化：解码侧 batch 小、TPOT 敏感，正是低延迟 NVLink All-to-All 的甜点区；预填侧 batch 大、吞吐优先，All-to-All 的固定开销被摊薄，但跨域流量集中在预填侧，专家放置需按预填池的拓扑重新约束。若两侧共用同一套专家放置，解码侧会被预填侧拉高的跨域比例拖累，因此分离式部署下应允许两池各自独立的专家放置策略——这是组合选型时必须显式决策的点，而非默认继承。与投机解码组合时，验证阶段一次前向要处理多倍 token，dispatch 的 <span class=\"formula-inline\">S</span> 变大，重叠窗口更饱满，All-to-All 的相对开销下降；但草稿模型与主模型的专家集合若不一致，跨模型搬运会引入额外一跳，选型时需确认二者共享同一专家并行拓扑，否则投机带来的时延收益会被额外 All-to-All 抵消。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-55\">五十五 · 否决条件与回退路径</h3>\n<p>给出三条硬否决，命中任一条即不应选 All-to-All EP：其一，专家权重总量超出单卡显存预算，无法做到每卡持有本地专家全集——这是本算法的结构性前提，不满足则一切重叠设计无意义；其二，跨节点 IB 流量占比在 profiler 中持续高于域内流量，说明专家放置已失控，重叠收益被跨域延迟吞掉，回退到 TP 或专家复制；其三，集群存在显著异构（卡型或网络路径不一致），combine 的木桶效应会把整层时延钉在最慢 rank 上，此时应改用对尾延迟不敏感的集合通信方案。回退路径按代价排序：先尝试重排专家放置把跨域比例压回 NVLink 域内（改动最小，收益最直接）；再考虑 TP+EP 混合，把高频专家放域内、低频专家走跨域；最后才是放弃 EP 改纯 TP，代价是放弃稀疏搬运的带宽优势。</p>\n<p>工程判断落在一条可执行规则上：把 <span class=\"formula-inline\">T_dispatch/T_GEMM</span> 的实测比值作为常规监控指标，比值随 batch 与专家放置漂移；当该比值在小 batch 解码下持续大于 1，说明当前拓扑已不适合继续用 All-to-All 承载该模型的解码流量，应触发专家放置重排或切换并行策略，而不是继续在重叠调度上做微调。</p>\n\n<h3 id=\"alg-moe-alltoall-ep-sec-56\">五十六 · 同族对照：何时该用 All-to-All 重叠，何时该退回别的形态</h3>\n<p>把本方案放回同族算法谱系里，对照维度只有三个：token 是否真的需要跨设备、跨域流量占比、以及 batch 大小是否撑得起重叠窗口。第一个对照对象是<strong>逐专家独立 launch 的朴素实现</strong>：它先全量 dispatch 再串行分组 GEMM，流水线里通信与计算严格串行，层时延退化为 $T_{\\text{dispatch}}+T_{\\text{GEMM}}+T_{\\text{combine}}$，而本方案把前两项压成 $\\max(T_{\\text{dispatch}},T_{\\text{GEMM}})$。差别不在算法而在调度：朴素实现没有任何隐藏通信的机会，只要 $T_{\\text{dispatch}}$ 占比超过三成，重叠版就必然更优；反过来，若专家数极少、单卡即可容纳全部专家（EP=1 或专家与 rank 一一对应且无跨卡路由），dispatch 退化为本地 scatter，此时朴素实现反而省掉元数据打包与 barrier 开销，重叠框架的收益为零而固定成本为正。第二个对照对象是<strong>纯张量并行</strong>：TP 每层搬全量激活，通信量随 hidden 维线性增长且与路由稀疏性无关；All-to-All 只搬被路由到的 token，搬运量正比于 $S\\cdot k$ 而非 $S\\cdot d$ 的全量复制。当 TopK 远小于专家总数、路由分布集中时，稀疏搬运的字节数显著低于 TP 的全量 All-Reduce，这是本方案在 MoE 解码里胜出的结构性原因；但当专家总数很少、路由几乎均匀打满所有专家时，稀疏性消失，All-to-All 的搬运量逼近全量，TP 的规整集合通信反而在延迟上更可预测。</p>\n<p>第三个对照对象是<strong>专家复制/冗余放置</strong>与<strong>分层（节点内+节点间两级）All-to-All</strong>。前者用显存换带宽：把热门专家在多个 rank 上各放一份，让 router 优先路由到本地副本，从而把跨域 token 数压下来，代价是显存占用按复制倍数上升、且需要一致性或版本同步机制；后者把一次全局 All-to-All 拆成节点内 NVLink 交换加节点间 IB 交换两级，降低单次集合通信的规模但引入两次同步点。选择判据可以写成一条粗略的不等式：设跨域 token 比例为 $\\rho$，则只有当 $\\rho\\cdot T_{\\text{dispatch}}^{\\text{IB}} &lt; T_{\\text{GEMM}}$ 时，重叠才有意义地把通信藏进计算；一旦 $\\rho$ 上升到使 IB 段时延超过 GEMM 时间，重叠设计失效，此时应优先改专家放置或引入专家复制，而不是继续调 All-to-All 的 kernel 参数。这也是本方案与 DeepEP 低延迟模式的耦合点：低延迟模式在 NVLink 域内绕开 IB，本质上是把 $\\rho$ 强制压到接近零，因此它的适用条件就是“专家放置被约束在单 NVLink 域内”，一旦拓扑被迫跨域，模式切换回高吞吐路径，解码小 batch 的固定开销立刻显性化。</p>\n<p>决策表按工程可观测的量来组织，而不是按论文里的抽象分类：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选形态</th><th>系统代价与失效点</th></tr></thead><tbody><tr><td>解码小 batch、TopK 稀疏、专家全在单 NVLink 域</td><td>All-to-All + 分组 GEMM 重叠（DeepEP 低延迟）</td><td>收益最大；失效点是误走 IB 路径，固定开销吞掉重叠</td></tr><tr><td>跨节点比例 $\\rho$ 高、IB 带宽受限</td><td>专家复制/本地优先路由，或两级分层 All-to-All</td><td>显存按复制倍数上涨；两级同步点增加层时延抖动</td></tr><tr><td>专家数少、路由近均匀、EP 接近 1</td><td>朴素逐专家 launch 或 TP</td><td>重叠框架固定成本为正而收益为零</td></tr><tr><td>prefill 大 batch、计算主导</td><td>高吞吐 All-to-All 路径，弱化低延迟模式</td><td>重叠窗口被长 GEMM 吸收，通信不再是瓶颈</td></tr></tbody></table>\n<p>最后落在失效条件的量化判断上：combine 的木桶效应无法用重叠消除，因为 $T_{\\text{combine}}$ 必须等所有专家 rank 完成，整层时延由最慢 rank 决定，这与 dispatch 的可重叠性形成不对称——dispatch 能藏，combine 不能。因此调度器的实际优化目标不是最小化平均通信时间，而是最小化 $\\max_r T_{\\text{combine}}^{(r)}$，即压住尾部 rank。工程上的直接手段是让专家放置与路由分布对齐，使各 rank 的 token 数与 GEMM 工作量均衡；若某 rank 因承载热门专家而持续成为尾部，则应把它拆分为多副本或迁移到 NVLink 域内更靠近 router 的位置。判断是否该继续投入本方案的信号很明确：当 profiling 显示 $T_{\\text{dispatch}}$ 已被 GEMM 完全覆盖、而层时延仍由单一 rank 的 combine 拖住时，瓶颈已从通信带宽转移到负载均衡，继续调 All-to-All 的桶大小与流水深度不再有边际收益，应转向专家放置与副本策略。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 分离式预填/解码与批调度</td></tr><tr><td>解决什么</td><td>MoE 专家分散在多卡/多节点，token 需跨设备搬运到目标专家所在 GPU，All-to-All 的带宽与延迟成为…</td></tr><tr><td>一句话机制</td><td>将 token 按目标专家 rank 分桶，用 NVLink/NVSwitch 的 All-to-All 与分组 GE…</td></tr><tr><td>代价与失效</td><td>跨节点 IB All-to-All 带宽远低于 NVLink，专家放置不当会放大跨域流量；combine 阶段必须等所有专家完成，最慢 r…</td></tr><tr><td>后继</td><td>专家缓存与双阶段预取</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-moe-alltoall-ep · 共 8 个片段</p>\n";break;}}})();
